export const INSTRUMENTS_QUESTIONS: AirLawQuestion[] = [
  // ── Ch1 Temperature & Pressure Measurement → A.7.5 ──
  { id: "INS-0101", sectionId: "A.7.5", question: "TAT is equal to RAT when:", optionA: "the aircraft is operating in ISA conditions at sea level", optionB: "the aircraft is operated at speeds above Mach 0.3", optionC: "at any temperature where the recovery factor is less than 1.00", optionD: "the recovery factor of the temperature sensor is equal to 1.00", correctAnswer: "d", explanation: "TAT (total air temperature) includes 100% of the ram rise; the probe reads all of the ram rise only when its recovery factor is 1.00, so RAT then equals TAT.", difficulty: "medium" },
  { id: "INS-0102", sectionId: "A.7.5", question: "TAT is:", optionA: "equal to SAT + ram rise", optionB: "equal to RAT - ram rise", optionC: "always the same as RAT in ISA conditions at any flight level", optionD: "the temperature read from the temperature gauge minus the recovery factor", correctAnswer: "a", explanation: "Total air temperature is the static (ambient) air temperature plus the full ram rise.", difficulty: "medium" },
  { id: "INS-0103", sectionId: "A.7.5", question: "If the TAS is 200 kt the ram rise is approximately:", optionA: "6°", optionB: "5°", optionC: "4°", optionD: "2°", correctAnswer: "c", explanation: "Ram rise ≈ (TAS/100)² = (200/100)² = 4 °C.", difficulty: "medium" },
  { id: "INS-0104", sectionId: "A.7.5", question: "The operating principle of the direct reading thermometer is based on:", optionA: "the pressure of air against a bi-metallic spring, the compression of which drives the needle of the indicator", optionB: "the different coefficients of expansion of two different metals", optionC: "the measurement of the electrical resistance between two different metals", optionD: "the similar coefficients of expansion of two different metals", correctAnswer: "b", explanation: "A direct-reading (bi-metallic) thermometer works because two bonded metals with different expansion coefficients bend/coil as temperature changes.", difficulty: "medium" },
  { id: "INS-0105", sectionId: "A.7.5", question: "The operating principle of the electrical thermometer is based on:", optionA: "the change in the electrical resistance between two different metals", optionB: "the different coefficients of expansion of two different metals", optionC: "the change in the electrical resistance with temperature", optionD: "the similar coefficients of expansion of two different metals", correctAnswer: "c", explanation: "An electrical (resistance) thermometer relies on a metal's electrical resistance rising with temperature, measured by a Wheatstone bridge.", difficulty: "medium" },
  { id: "INS-0106", sectionId: "A.7.5", question: "An aneroid capsule:", optionA: "has an opening which allows it to be connected to a pressure source", optionB: "is commonly used to measure the difference between two pressures", optionC: "is ideal for measuring high pressure systems such as engine oil", optionD: "is sealed and contains a partial vacuum", correctAnswer: "d", explanation: "An aneroid capsule is sealed with a partial vacuum inside, so it expands/contracts with changes in the surrounding pressure (used in altimeters).", difficulty: "medium" },
  { id: "INS-0107", sectionId: "A.7.5", question: "With reference to temperature measurement: (1) A Bourdon Tube thermometer operates on the principle of the differential expansion of two metals. (2) The system which operates on the principle of expansion and contraction of liquid is called a Bourdon Tube. (3) A Wheatstone bridge measures the decrease in electrical resistance as temperature increases. (4) Temperature measurement caused by the differential expansion of two metals is the operating principle of an electrical thermometer. (5) The bi-metallic thermometer operates on the principle of the differential expansion of two metals.", optionA: "2 and 5 are correct", optionB: "1, 3 and 4 are correct", optionC: "2, 3 and 5 are correct", optionD: "1 and 3 are correct", correctAnswer: "a", explanation: "Only (2) — the Bourdon tube uses liquid/gas expansion — and (5) — the bi-metallic thermometer uses differential metal expansion — are correct.", difficulty: "hard" },
  { id: "INS-0108", sectionId: "A.7.5", question: "With reference to temperature: (1) The freezing point of water is -32°F. (2) The boiling point of water is 212°F. (3) 50°F is the same as 10°C. (4) To convert °C to °K, multiply by 5 and divide by 9. (5) 22°C is the same as 65°F.", optionA: "1, 2 and 5 are correct", optionB: "2 and 3 are correct", optionC: "1, 4 and 5 are correct", optionD: "2 and 5 are correct", correctAnswer: "b", explanation: "Water freezes at 32°F (not −32) and boils at 212°F; 50°F = 10°C; °K = °C + 273; 22°C = 71.6°F. Only (2) and (3) are correct.", difficulty: "hard" },
  { id: "INS-0109", sectionId: "A.7.5", question: "With reference to pressure measurement: (1) A reduction in pressure will cause an aneroid capsule to contract. (2) A pressure capsule is used to measure changes in pressure. (3) To measure the difference between two sensed pressures a bellows system is used. (4) A bellows system is used to measure an increase or decrease in pressure. (5) An aneroid capsule is a sealed capsule containing a partial vacuum. (6) A pressure capsule is able to expand or contract with changes in pressure.", optionA: "1, 2 and 4 are correct", optionB: "2, 4 and 5 are correct", optionC: "1, 5 and 6 are wrong", optionD: "3, 5 and 6 are correct", correctAnswer: "b", explanation: "A pressure reduction lets a sealed aneroid EXPAND (not contract); the bellows compares two pressures. Statements 2, 4 and 5 are correct.", difficulty: "hard" },
  { id: "INS-0110", sectionId: "A.7.5", question: "With reference to pressure and temperature measuring systems:", optionA: "a Bourdon tube can only be used to measure changes in temperature", optionB: "a pressure capsule expands with a decrease in pressure", optionC: "the electrical resistance of a material increases with a rise in temperature", optionD: "the metals used in a bi-metallic thermometer must have the same coefficients of expansion", correctAnswer: "c", explanation: "Electrical (resistance) thermometers rely on resistance rising with temperature. A Bourdon tube measures pressure or temperature; a pressure capsule contracts (not expands) with rising external pressure; bi-metallic strips need DIFFERENT expansion coefficients.", difficulty: "medium" },

  // ── Ch2 Pitot-Static System → A.7.1 ──
  { id: "INS-0201", sectionId: "A.7.1", question: "The location of the static vent which would provide the most accurate measurement of static pressure under variable flight conditions is:", optionA: "at the side of a Pitot-static head because it would encounter relatively undisturbed air", optionB: "in the cockpit because the static pressure here is always the same as external static pressure", optionC: "one on each side of the aircraft's fuselage", optionD: "at the rear of the pitot-static head because it would never encounter turbulent air", correctAnswer: "c", explanation: "A static vent on each side of the fuselage (static balancing) cancels the errors introduced by sideslip and manoeuvring.", difficulty: "medium" },
  { id: "INS-0202", sectionId: "A.7.1", question: "During flight, total pressure is sensed by:", optionA: "the front facing hole of the pitot tube", optionB: "a small vent at the rear of the pitot head", optionC: "a small vent at the bottom of the pitot head", optionD: "two vents, one on either side of the fuselage", correctAnswer: "a", explanation: "The forward-facing pitot hole senses total (pitot) pressure = dynamic + static.", difficulty: "easy" },
  { id: "INS-0203", sectionId: "A.7.1", question: "Position error may be reduced by:", optionA: "making use of a single pitot-static head rather than a separate pitot tube and static vent", optionB: "mounting a static vent on each side of the aircraft's fuselage", optionC: "making use of two pitot tubes, one located on each side of the forward fuselage", optionD: "positioning the pitot tube at the front of the nose of the aircraft", correctAnswer: "b", explanation: "A static vent on each side of the fuselage (static balancing) reduces position/manoeuvre-induced error.", difficulty: "medium" },
  { id: "INS-0204", sectionId: "A.7.1", question: "In an unpressurised aircraft the alternate static vent:", optionA: "draws static pressure from a second static vent mounted on the side of the fuselage", optionB: "draws static pressure from a vent at the rear of the pitot-static head", optionC: "is activated by the 'alternate air' control", optionD: "draws static pressure from within the aircraft's cabin", correctAnswer: "d", explanation: "The alternate static source admits cabin static pressure; in an unpressurised aircraft cabin pressure is close to (slightly below) external static.", difficulty: "medium" },
  { id: "INS-0205", sectionId: "A.7.1", question: "Pitot pressure:", optionA: "is the sum of dynamic pressure and static pressure", optionB: "is dynamic pressure minus static pressure", optionC: "is static pressure minus dynamic pressure", optionD: "plus static pressure equals dynamic pressure", correctAnswer: "a", explanation: "Pitot (total) pressure = dynamic pressure + static pressure.", difficulty: "easy" },
  { id: "INS-0206", sectionId: "A.7.1", question: "If Total pressure is represented by Pt and static pressure by Ps, then dynamic pressure is:", optionA: "Pt + Ps", optionB: "Pt ÷ Ps", optionC: "Pt × Ps", optionD: "Pt - Ps", correctAnswer: "d", explanation: "Dynamic = total − static (Pt − Ps).", difficulty: "easy" },
  { id: "INS-0207", sectionId: "A.7.1", question: "Random changes in the pressure at the static vents is referred to as:", optionA: "static error", optionB: "manoeuvre induced error", optionC: "position error", optionD: "total pressure error", correctAnswer: "b", explanation: "Random pressure fluctuations from manoeuvring (sideslip, turbulence) are manoeuvre-induced error, and cannot be corrected.", difficulty: "medium" },
  { id: "INS-0208", sectionId: "A.7.1", question: "During flight the front facing hole of the pitot tube senses:", optionA: "dynamic pressure only", optionB: "static pressure only", optionC: "dynamic pressure minus static pressure", optionD: "dynamic pressure and static pressure", correctAnswer: "d", explanation: "The pitot hole senses total pressure = dynamic + static.", difficulty: "easy" },
  { id: "INS-0209", sectionId: "A.7.1", question: "With reference to pitot and static pressure: (1) Dynamic and static pressure is measured by a pitot head. (2) A static vent measures static and dynamic pressure. (3) Manoeuvre induced error is caused by temporary pressure changes at a static vent. (4) Position error is primarily caused by changes in aircraft configuration. (5) Manoeuvre induced error is permanent in nature and flight tests will produce a correction table.", optionA: "1, 2 and 5 are correct", optionB: "2, 3 and 5 are correct", optionC: "1, 3 and 4 are correct", optionD: "3, 4 and 5 are correct", correctAnswer: "c", explanation: "A pitot head senses total pressure (1); a static vent senses only static (2 wrong); manoeuvre error is temporary and uncorrectable (5 wrong). Statements 1, 3 and 4 are correct.", difficulty: "hard" },

  // ── Ch3 Pressure Altimeter → A.7.1 ──
  { id: "INS-0301", sectionId: "A.7.1", question: "The time lag error in a sensitive altimeter is such that:", optionA: "when levelling off from a rapid descent the response to the change in height is instantaneous", optionB: "when levelling off from a rapid descent the altimeter will over-read for a brief period", optionC: "when levelling off from a rapid descent the altimeter will under-read for a brief period", optionD: "when levelling off from a rapid climb the altimeter will over-read for a brief period", correctAnswer: "b", explanation: "Lag means the altimeter keeps indicating the earlier value briefly — after a rapid descent it still shows the higher altitude, i.e. it over-reads for a moment.", difficulty: "medium" },
  { id: "INS-0302", sectionId: "A.7.1", question: "In a sensitive altimeter:", optionA: "static pressure is fed to the capsules, whilst the pressure inside the case remains constant", optionB: "a single capsule is used to drive the instrument's needles", optionC: "the use of two or three capsules measures pressure changes more accurately and increases the movement necessary to drive the instrument's three needles", optionD: "'E' and 'I' bars are used to drive the linkage system between the capsules and the instrument's needles", correctAnswer: "c", explanation: "The sensitive altimeter stacks two or three capsules to give greater deflection/accuracy and enough movement to drive the multiple pointers.", difficulty: "medium" },
  { id: "INS-0303", sectionId: "A.7.1", question: "During a climb a sensitive altimeter operates on the principle that:", optionA: "a reduction in static pressure entering the capsules causes them to contract", optionB: "the delayed static pressure entering the capsules allows them to expand", optionC: "a reduction in static pressure entering the instrument case causes the capsules to expand", optionD: "static pressure entering the instrument case causes the capsules to contract", correctAnswer: "c", explanation: "Static pressure is fed to the sealed CASE; in a climb case pressure falls, so the evacuated capsules expand.", difficulty: "medium" },
  { id: "INS-0304", sectionId: "A.7.1", question: "The method of operation of a sensitive altimeter is that:", optionA: "static pressure is fed to the capsules and the instrument case", optionB: "total pressure is fed to the instrument case and static pressure to the capsules", optionC: "the instrument case contains a partial vacuum and static pressure is fed to the capsules", optionD: "the capsules contain a partial vacuum and static pressure is fed to the instrument case", correctAnswer: "d", explanation: "The capsules are evacuated (partial vacuum) and static pressure is fed to the airtight case, so the capsules expand/contract with altitude.", difficulty: "medium" },
  { id: "INS-0305", sectionId: "A.7.1", question: "In a servo-assisted altimeter:", optionA: "the capsules are connected to the 'I' bar, the movement of which varies the output from the outer limbs of the 'E' bar", optionB: "the capsules are connected to the 'E' bar, the movement of which varies the output from the 'I' bar", optionC: "the capsules are connected directly to the servo motor which drives the 'E' and 'I' bars", optionD: "the capsules are connected to the 'I' bar, the movement of which ensures that the output from the outer limbs of the 'E' bar are equal at all times", correctAnswer: "a", explanation: "Capsule movement deflects the 'I' bar of the E-and-I pick-off, unbalancing the air gaps and generating the output that drives the servo.", difficulty: "hard" },
  { id: "INS-0306", sectionId: "A.7.1", question: "In a simple altimeter:", optionA: "a minimum of two capsules are used", optionB: "the instrument can only be set to indicate the altitude above sea level when the aircraft is on the ground", optionC: "three pointers are visible on the face of the instrument", optionD: "a subscale window is incorporated allowing local QNH, QFE or 1013 hPa to be set during flight", correctAnswer: "b", explanation: "A simple altimeter has a single capsule and no barometric subscale; it can only be re-set (to zero or to elevation) on the ground.", difficulty: "medium" },
  { id: "INS-0307", sectionId: "A.7.1", question: "An altitude alerting system will provide a pilot with an audio and a visual warning when:", optionA: "it is approaching within 500 ft of the pre-set cruising level", optionB: "it is approaching within 1500 ft of the pre-set cruising level", optionC: "the aircraft deviates from the pre-set cruising level by more than 500 ft", optionD: "the aircraft deviates from the pre-set cruising level by 250 to 300 ft", correctAnswer: "d", explanation: "The alerter warns approaching (~1000 ft to go) and again if the aircraft departs the selected level by about 250–300 ft.", difficulty: "medium" },
  { id: "INS-0308", sectionId: "A.7.1", question: "The servo altimeter incorporates a servo motor which:", optionA: "links the 'I' bar to the indicators", optionB: "joins the capsules to the 'I' bar", optionC: "drives the indicators and the cam", optionD: "is used by the 'I' bar to drive the 'E' bar", correctAnswer: "c", explanation: "The amplified pick-off signal drives the servo motor, which turns the pointers/drums and the cam follower.", difficulty: "medium" },
  { id: "INS-0309", sectionId: "A.7.1", question: "The principle of operation of a servo-assisted altimeter is that:", optionA: "movement of the capsules drives an 'I' bar which induces an AC current in the 'E' bar, which is amplified before being fed to the servo motor which drives the pointers", optionB: "movement of the capsules drives an 'E' bar which induces an AC current in the 'I' bar, which is amplified before being fed to the servo motor which drives the pointers", optionC: "the capsules are directly attached to a worm gear and cam which drives the servo motor", optionD: "the subscale setting knob is directly attached to a servo motor which turns the indicators", correctAnswer: "a", explanation: "Capsule movement deflects the 'I' bar in the E/I inductive pick-off, producing an AC output that is amplified and drives the servo motor and pointers.", difficulty: "hard" },
  { id: "INS-0310", sectionId: "A.7.1", question: "With reference to altimeter errors:", optionA: "time lag error does not occur in the simple altimeter because there is only one capsule", optionB: "in the servo assisted altimeter time lag error is virtually eliminated", optionC: "pressure, or position, error does not occur in the servo altimeter because capsules are not used", optionD: "the use of two or three capsules in the sensitive altimeter eliminates temperature error", correctAnswer: "b", explanation: "The servo altimeter's electrical pick-off virtually removes the mechanical time-lag error of geared instruments.", difficulty: "medium" },
  { id: "INS-0311", sectionId: "A.7.1", question: "Pressure altitude 10 000 feet, OAT +5°C. The Density Altitude is:", optionA: "11 500 ft", optionB: "12 300 ft", optionC: "9 200 ft", optionD: "10 000 ft", correctAnswer: "a", explanation: "ISA at 10 000 ft = −5°C, so OAT +5° is 10° warmer than ISA; DA ≈ PA + (118.8 × ISA deviation) ≈ 10 000 + ~1188, giving about 11 500 ft (by navigation computer).", difficulty: "hard" },
  { id: "INS-0312", sectionId: "A.7.1", question: "Pressure Altitude 15 000 ft, QNH Altitude 16 000 ft, OAT +10°C. The true altitude is:", optionA: "15 900 ft", optionB: "16 450 ft", optionC: "17 600 ft", optionD: "16 820 ft", correctAnswer: "c", explanation: "Warmer-than-ISA air raises true altitude above QNH altitude; correcting the 16 000 ft QNH altitude for the positive temperature deviation gives ≈ 17 600 ft.", difficulty: "hard" },
  { id: "INS-0313", sectionId: "A.7.1", question: "Pressure Altitude 8000 ft, QNH Altitude 7500 ft, OAT +30°C, terrain elevation 5700 ft. The approximate absolute altitude is:", optionA: "500 ft", optionB: "1800 ft", optionC: "2650 ft", optionD: "2350 ft", correctAnswer: "c", explanation: "True altitude ≈ 8350 ft (temperature-corrected); absolute altitude = true altitude − terrain elevation = 8350 − 5700 ≈ 2650 ft.", difficulty: "hard" },
  { id: "INS-0314", sectionId: "A.7.1", question: "Airfield Elevation 4000 ft, OAT +15°C, QNH 995 hPa. The Density Altitude is:", optionA: "5000 ft", optionB: "5600 ft", optionC: "6200 ft", optionD: "5400 ft", correctAnswer: "b", explanation: "Pressure altitude = 4000 + (1013−995)×30 = 4546 ft; correcting for the +9° ISA deviation gives DA ≈ 5600 ft.", difficulty: "hard" },
  { id: "INS-0315", sectionId: "A.7.1", question: "Pressure Altitude at an airfield is indicated by an altimeter when the barometric sub-scale is set to:", optionA: "airfield QNH", optionB: "QFE", optionC: "1013 hPa", optionD: "sea level QNH", correctAnswer: "c", explanation: "With the standard 1013.25 hPa set, the altimeter reads pressure altitude (height above the 1013 hPa datum).", difficulty: "medium" },
  { id: "INS-0316", sectionId: "A.7.1", question: "If an altimeter indicates 3500 feet with QNH 1004 hPa set, the pressure altitude is:", optionA: "3770 ft", optionB: "3500 ft", optionC: "3160 ft", optionD: "3245 ft", correctAnswer: "a", explanation: "1013 − 1004 = 9 hPa × 30 ft = 270 ft; pressure altitude = 3500 + 270 = 3770 ft (lower pressure setting → higher PA).", difficulty: "medium" },
  { id: "INS-0317", sectionId: "A.7.1", question: "An altimeter is set to 1011 hPa. The aircraft lands at an airfield (elevation 772 feet AMSL, QNH 1016 hPa). On landing the altimeter will read:", optionA: "932 ft", optionB: "160 ft", optionC: "622 ft", optionD: "922 ft", correctAnswer: "c", explanation: "QNH 1016 vs set 1011 = 5 hPa × 30 = 150 ft; the altimeter under-reads elevation by 150 ft: 772 − 150 = 622 ft.", difficulty: "medium" },
  { id: "INS-0318", sectionId: "A.7.1", question: "En route at FL 270, the altimeter is set correctly. On the descent the pilot fails to reset the altimeter to QNH 1026. If the airfield elevation is 1300 feet, after landing the altimeter will indicate:", optionA: "1690 ft", optionB: "910 ft", optionC: "390 ft", optionD: "1300 ft", correctAnswer: "b", explanation: "Left on 1013 instead of QNH 1026: 1026 − 1013 = 13 hPa × 30 = 390 ft under-read; 1300 − 390 = 910 ft.", difficulty: "medium" },
  { id: "INS-0319", sectionId: "A.7.1", question: "An aircraft flies from Grand Central (QNH 1029 hPa) to Cape Town (QNH 1015 hPa) at FL 160. In the cruise the aircraft is:", optionA: "descending", optionB: "climbing", optionC: "maintaining altitude", optionD: "unable to be determined", correctAnswer: "a", explanation: "Flying from high pressure to low pressure at constant flight level, true altitude decreases — the aircraft is descending.", difficulty: "medium" },
  { id: "INS-0320", sectionId: "A.7.1", question: "An airfield, elevation 3000 feet, has a pressure altitude of 3480 feet. The QNH and QFE respectively is:", optionA: "1029 hPa and 913 hPa", optionB: "1013 hPa and 879 hPa", optionC: "1029 hPa and 997 hPa", optionD: "997 hPa and 897 hPa", correctAnswer: "d", explanation: "PA − elevation = 480 ft ÷ 30 = 16 hPa; QNH = 1013 − 16 = 997; QFE = QNH − (3000/30) = 997 − 100 = 897 hPa.", difficulty: "hard" },
  { id: "INS-0321", sectionId: "A.7.1", question: "An aircraft is flying at FL 120, the QNH is 995 hPa. The clearance the aircraft would have over high ground 6500 ft AMSL is:", optionA: "4960 feet", optionB: "6040 feet", optionC: "6250 feet", optionD: "4420 feet", correctAnswer: "a", explanation: "1013 − 995 = 18 hPa × 30 = 540 ft; true altitude = 12 000 − 540 = 11 460 ft; clearance = 11 460 − 6500 = 4960 ft.", difficulty: "hard" },
  { id: "INS-0322", sectionId: "A.7.1", question: "An aircraft is maintaining FL150 when the static vents become blocked. If no other action is taken, on descending past the transition level of FL090, the altimeter will:", optionA: "over-read by the difference between local QNH and 1013 hPa", optionB: "under-read by the difference between local QNH and 1013 hPa", optionC: "indicate zero", optionD: "still indicate FL150", correctAnswer: "d", explanation: "A blocked static vent traps the pressure, so the altimeter freezes at the last value — it still indicates FL150.", difficulty: "medium" },
  { id: "INS-0323", sectionId: "A.7.1", question: "Airfield A - Elevation 2100 feet, QFE 930 hPa. Airfield B - Elevation 1200 feet. A pilot sets airfield elevation on his altimeter prior to take-off from A. On landing at B the altimeter reads 1500 feet. The QNH at B is:", optionA: "990 hPa", optionB: "1010 hPa", optionC: "940 hPa", optionD: "980 hPa", correctAnswer: "a", explanation: "QNH at A = 930 + (2100/30) = 1000 hPa; the altimeter over-reads B's elevation by 300 ft = 10 hPa, so QNH at B = 1000 − 10 = 990 hPa.", difficulty: "hard" },
  { id: "INS-0324", sectionId: "A.7.1", question: "An aircraft leaves A (elevation 540 feet) with QFE 1008 hPa set on the altimeter, en route to B (1000 nm from A, QNH 1000 hPa). A spot height 232 metres AMSL, 250 nm from A is cleared by 1500 feet. The altimeter reading over the spot height is:", optionA: "1916 feet", optionB: "2261 feet", optionC: "2606 feet", optionD: "1981 feet", correctAnswer: "a", explanation: "Spot height = 232 m × 3.28 = 761 ft; true height over it = 761 + 1500 = 2261 ft; with QFE 1008 set (reads height above A) and the QNH falling ~6.5 hPa over 250 nm, the altimeter reads about 1916 ft.", difficulty: "hard" },
  { id: "INS-0325", sectionId: "A.7.1", question: "An aircraft leaves Y, airfield pressure 960 hPa, and the altimeter reads airfield elevation of 1860 feet. The aircraft lands at Z (elevation 1000 feet) where the altimeter reads 1270 feet. The QNH at Z is:", optionA: "1013 hPa", optionB: "1022 hPa", optionC: "1031 hPa", optionD: "1008 hPa", correctAnswer: "a", explanation: "QNH at Y = 960 + (1860/30) = 1022 hPa; the altimeter over-reads Z's elevation by 270 ft = 9 hPa, so QNH at Z = 1022 − 9 = 1013 hPa.", difficulty: "hard" },
  { id: "INS-0326", sectionId: "A.7.1", question: "The elevation of an aerodrome is 3400 ft, QNH 1023 at the aerodrome. If the transition level is FL060, the height of the transition level above the aerodrome is:", optionA: "2306 ft", optionB: "2422 ft", optionC: "2754 ft", optionD: "2894 ft", correctAnswer: "d", explanation: "With 1013 set, FL060 is 6000 ft above the 1013 datum; the aerodrome (QNH 1023) sits (1023−1013)×30 = 294 ft above that datum at elevation 3400, so the transition level is 6000 − 294 − (aerodrome offset) ≈ 2894 ft above the aerodrome.", difficulty: "hard" },
  { id: "INS-0327", sectionId: "A.7.1", question: "During a pre-flight check the following details were noted: Airfield Elevation 5000 feet; Apron Elevation 4980 feet; Height of static vent above ground 25 feet; Altimeter reading (QFE set) 45 feet. The instrument error is:", optionA: "40 ft under-read", optionB: "5 ft under-read", optionC: "45 ft over-read", optionD: "40 ft over-read", correctAnswer: "d", explanation: "With QFE set the altimeter should read the static-vent height (5 ft above the 4980 ft apron relative to the 5000 ft datum); it reads 45 ft, i.e. 40 ft too high — a 40 ft over-read.", difficulty: "hard" },
  { id: "INS-0328", sectionId: "A.7.1", question: "With reference to the sensitive altimeter: (1) The purpose of the jewelled bearings is to compensate for temperature changes. (2) A bi-metallic strip is incorporated in the linkage system to reduce friction and time lag. (3) The barometric subscale mechanism forms part of the mechanical linkage system. (4) Temperature changes are compensated for by the positioning of a bi-metallic strip between the capsules and the transmission shaft. (5) The use of a single large capsule makes the system far more sensitive than the simple altimeter.", optionA: "1, 2 and 3 are correct", optionB: "2, 3 and 5 are correct", optionC: "3 and 4 are correct", optionD: "1, 3 and 5 are correct", correctAnswer: "c", explanation: "Jewelled bearings reduce friction (not temperature); the bi-metallic strip compensates temperature (not friction/lag); the sensitive altimeter uses multiple capsules. Only (3) and (4) are correct.", difficulty: "hard" },

  // ── Ch4 Airspeed Indicator → A.7.1 ──
  { id: "INS-0401", sectionId: "A.7.1", question: "If the Pitot head became blocked:", optionA: "there would be no change of IAS in level flight, even with large power changes", optionB: "the IAS will fall to zero", optionC: "there would be a constant IAS during a descent", optionD: "the IAS would decrease during a climb due to increasing static pressure", correctAnswer: "a", explanation: "A blocked pitot traps total pressure; in level flight (static unchanged) the IAS stays put regardless of power. It errs only when altitude changes.", difficulty: "medium" },
  { id: "INS-0402", sectionId: "A.7.1", question: "If the static vent became blocked during a descent the ASI would:", optionA: "show the speed at which the blockage occurred", optionB: "show zero", optionC: "underread", optionD: "overread", correctAnswer: "d", explanation: "With static trapped (too low), the descent's rising real static makes the ASI over-read.", difficulty: "medium" },
  { id: "INS-0403", sectionId: "A.7.1", question: "Calibrated Airspeed is:", optionA: "IAS corrected for instrument and pressure error", optionB: "EAS corrected for density error", optionC: "IAS corrected for density and compressibility errors", optionD: "IAS corrected for pressure error only", correctAnswer: "a", explanation: "CAS (= RAS) is IAS corrected for instrument and pressure (position) error.", difficulty: "medium" },
  { id: "INS-0404", sectionId: "A.7.1", question: "Equivalent airspeed (EAS) is:", optionA: "IAS corrected for density", optionB: "CAS corrected for density", optionC: "IAS corrected for instrument and pressure error", optionD: "CAS corrected for compressibility", correctAnswer: "d", explanation: "EAS = CAS corrected for compressibility; correcting EAS for density then gives TAS.", difficulty: "medium" },
  { id: "INS-0405", sectionId: "A.7.1", question: "If an aircraft is flying from a cold air mass into a warm air mass:", optionA: "the TAS will remain constant in level flight", optionB: "the TAS will decrease in level flight", optionC: "the TAS will increase in level flight", optionD: "the EAS will increase", correctAnswer: "c", explanation: "Warmer air is less dense; at constant IAS the TAS increases.", difficulty: "medium" },
  { id: "INS-0406", sectionId: "A.7.1", question: "During a climb the static line to the ASI becomes blocked:", optionA: "the ASI will continue to show the speed at which the blockage occurred", optionB: "the ASI reading will underread", optionC: "the ASI reading will overread", optionD: "the ASI will immediately fall to zero", correctAnswer: "b", explanation: "In a climb, real static falls but the trapped (too-high) static makes the ASI under-read.", difficulty: "medium" },
  { id: "INS-0407", sectionId: "A.7.1", question: "The yellow arc on an airspeed indicator represents:", optionA: "the speed at which flaps may be lowered or retracted", optionB: "the cautionary speed range", optionC: "the maximum speed at which the undercarriage may be lowered", optionD: "the maximum speed at which the aircraft may be operated", correctAnswer: "b", explanation: "The yellow arc (VNO to VNE) is the cautionary range — smooth air only.", difficulty: "easy" },
  { id: "INS-0408", sectionId: "A.7.1", question: "The lower end of the white arc on an airspeed indicator represents:", optionA: "the stalling speed with flaps fully retracted", optionB: "the beginning of the normal operating speed range", optionC: "the minimum speed for operations in turbulent air", optionD: "the stalling speed with full flap", correctAnswer: "d", explanation: "The white arc runs from VS0 (stall in the landing configuration, full flap) at its lower end to VFE at the top.", difficulty: "medium" },
  { id: "INS-0409", sectionId: "A.7.1", question: "An airspeed indicator operates on the principle that:", optionA: "pitot, or total, pressure minus static pressure is fed to the capsule and pure static pressure is fed to the instrument case", optionB: "pitot, or total, pressure minus static pressure is fed to the instrument case and pure static pressure is fed to the capsule", optionC: "static pressure is fed to the instrument case and pitot, or total, pressure to the capsule", optionD: "a sealed capsule containing a partial vacuum reacts to variations in the pitot pressure which is fed to the instrument case", correctAnswer: "c", explanation: "Static pressure fills the case and total (pitot) pressure inflates the capsule; the capsule reacts to the difference (dynamic pressure).", difficulty: "medium" },
  { id: "INS-0410", sectionId: "A.7.1", question: "An aircraft is maintaining a constant IAS in level flight. If the outside air temperature decreases the TAS will:", optionA: "decrease", optionB: "increase", optionC: "also remain constant", optionD: "fluctuate briefly before returning to the previous indication", correctAnswer: "a", explanation: "Colder air is denser; at constant IAS the TAS decreases.", difficulty: "medium" },
  { id: "INS-0411", sectionId: "A.7.1", question: "The effect of compressibility on an airspeed indicator:", optionA: "has no effect on the instrument because compensation is made by the incorporation of a bi-metallic strip in the mechanical linkage system", optionB: "causes the instrument to overread", optionC: "causes the instrument to underread", optionD: "is more noticeable at speeds below 300 kts", correctAnswer: "b", explanation: "Compressibility packs extra pressure into the capsule, so the ASI over-reads (correcting CAS for it gives the lower EAS).", difficulty: "medium" },
  { id: "INS-0412", sectionId: "A.7.1", question: "Compressibility error in an airspeed indicator:", optionA: "is more noticeable with a decrease in altitude", optionB: "decreases as the TAS increases", optionC: "increases as the IAS decreases", optionD: "increases as the TAS increases", correctAnswer: "d", explanation: "Compressibility error grows with speed and altitude — it increases as TAS increases.", difficulty: "medium" },
  { id: "INS-0413", sectionId: "A.7.1", question: "If during level flight the ASI reading falls to zero:", optionA: "the pitot head has become blocked", optionB: "the static vent may have become blocked", optionC: "there is a leak in the static system and alternate air should be selected", optionD: "the pitot head may have become blocked and there is also a leak in the pitot system", correctAnswer: "d", explanation: "Only if both total pressure is lost (pitot blocked) AND the capsule pressure bleeds away (a leak) will the ASI collapse to zero.", difficulty: "hard" },
  { id: "INS-0414", sectionId: "A.7.1", question: "Pressure altitude 14 000 ft, OAT -15, CAS 145 kts. The TAS is:", optionA: "178 kts", optionB: "168 kts", optionC: "145 kts", optionD: "181 kts", correctAnswer: "a", explanation: "Correcting 145 kt CAS for density (14 000 ft, −15 °C) on the navigation computer gives about 178 kt TAS.", difficulty: "hard" },
  { id: "INS-0415", sectionId: "A.7.1", question: "Pressure altitude 16 000 ft, OAT -18, TAS 190 kts. The CAS is:", optionA: "165 kts", optionB: "149 kts", optionC: "155 kts", optionD: "172 kts", correctAnswer: "b", explanation: "Working back from 190 kt TAS for the density at 16 000 ft / −18 °C gives ≈ 149 kt CAS.", difficulty: "hard" },
  { id: "INS-0416", sectionId: "A.7.1", question: "On an ASI VNO will be indicated by:", optionA: "a red line", optionB: "a blue line", optionC: "the top of the green arc where it meets the yellow arc", optionD: "the top of the white arc", correctAnswer: "c", explanation: "VNO (max structural cruising speed) is where the green arc ends and the cautionary yellow arc begins.", difficulty: "medium" },
  { id: "INS-0417", sectionId: "A.7.1", question: "With reference to the ASI: (1) CAS is equal to TAS when an aircraft is flying in conditions such that air density is 1225 grams per cubic metre, pressure is 1013.25 hPa and the temperature is +15°C. (2) TAS is CAS corrected for compressibility error. (3) An ASI operating in an air density lower than standard will indicate an airspeed lower than the TAS. (4) Corrections for manoeuvre induced error are listed in the Pilot's handbook. (5) Compressibility error will always cause the ASI to underread.", optionA: "1, 2 and 4 are correct", optionB: "1 and 3 are correct", optionC: "2, 3 and 5 are correct", optionD: "1, 4 and 5 are correct", correctAnswer: "b", explanation: "CAS = TAS at ISA sea level (1) and below-standard density makes the ASI under-read vs TAS (3). TAS is EAS (not CAS) corrected for density; manoeuvre error is uncorrectable; compressibility makes the ASI over-read.", difficulty: "hard" },
  { id: "INS-0418", sectionId: "A.7.1", question: "Using a rectified-airspeed compressibility-correction table (e.g. factor ≈ 0.99 at 15 000 ft / 250 kt): Pressure altitude 15 000 ft, CAS (RAS) 250 kts. The Equivalent airspeed (EAS) is:", optionA: "250 kts", optionB: "275 kts", optionC: "245 kts", optionD: "247.5 kts", correctAnswer: "d", explanation: "EAS = CAS × compressibility factor ≈ 250 × 0.99 = 247.5 kt.", difficulty: "hard" },
  { id: "INS-0419", sectionId: "A.7.1", question: "With reference to limiting speed terminology: (1) VS1 is the stall speed in the landing configuration and is indicated by the bottom of the white arc. (2) VS0 is the stalling speed with flaps retracted in level flight and is indicated by the bottom of the green arc. (3) VYSE is indicated by a blue line. (4) VFE is the maximum speed at which the aeroplane can be operated with the flaps extended. (5) VNO is indicated by a red line.", optionA: "3 and 4 are correct", optionB: "1, 2 and 5 are correct", optionC: "3, 4 and 5 are correct", optionD: "1, 3 and 4 are correct", correctAnswer: "a", explanation: "VYSE (blue line, 3) and VFE (top of white arc, 4) are correct. VS1 is bottom of green arc, VS0 bottom of white arc, and VNE (not VNO) is the red line.", difficulty: "hard" },
  { id: "INS-0420", sectionId: "A.7.1", question: "With reference to blockages and leaks during flight: (1) If the pitot head became blocked during a climb the ASI would overread. (2) If the static line became blocked in level flight the ASI reading would fall to zero. (3) If there was a leak in the static line during level flight the ASI would overread. (4) A blockage in the static pressure line during a descent would cause the ASI to underread. (5) A blockage in the pitot pressure line during a descent would cause the ASI to underread.", optionA: "2, 3 and 4 are correct", optionB: "2, 4 and 5 are correct", optionC: "1, 3 and 5 are correct", optionD: "1, 2 and 4 are correct", correctAnswer: "c", explanation: "Blocked pitot climbing → over-read (1); static-line leak in an unpressurised cabin admits higher cabin static → over-read (3); blocked pitot descending → under-read (5).", difficulty: "hard" },
  { id: "INS-0421", sectionId: "A.7.1", question: "The term 'True airspeed' (TAS) is used when:", optionA: "calibrated airspeed has been corrected for both density and compressibility errors", optionB: "indicated airspeed has been corrected for instrument and position error", optionC: "equivalent airspeed has been corrected for instrument and position error", optionD: "calibrated airspeed has been corrected for position and temperature error", correctAnswer: "a", explanation: "TAS = CAS corrected for compressibility (→ EAS) and then density.", difficulty: "medium" },

  // ── Ch5 Vertical Speed Indicator → A.7.1 ──
  { id: "INS-0501", sectionId: "A.7.1", question: "The construction of a vertical speed indicator (VSI) is such that:", optionA: "static pressure is supplied to the instrument case and delayed static pressure to the capsule", optionB: "delayed static pressure is supplied to the instrument case and static pressure to the capsule", optionC: "a capsule containing a partial vacuum is acted on by delayed static pressure supplied to the instrument case", optionD: "a capsule containing a partial vacuum is acted on by static pressure supplied to the instrument case", correctAnswer: "b", explanation: "Direct static feeds the capsule; static delayed by the metering choke fills the case, so a pressure differential appears whenever altitude is changing.", difficulty: "medium" },
  { id: "INS-0502", sectionId: "A.7.1", question: "During a climb a vertical speed indicator (VSI) will indicate a rate of climb because:", optionA: "delayed static pressure in the capsule allows it to expand", optionB: "static pressure in the capsule allows it to contract", optionC: "delayed static pressure in the instrument case allows the capsule to contract", optionD: "delayed static pressure in the instrument case allows the capsule to expand", correctAnswer: "d", explanation: "In a climb the direct static in the capsule falls faster than the delayed static in the case, so the capsule expands, showing a climb.", difficulty: "medium" },
  { id: "INS-0503", sectionId: "A.7.1", question: "If the alternate static source, which is vented inside an unpressurised aircraft, is activated in level flight:", optionA: "the VSI would indicate an initial climb for a few seconds before returning to zero", optionB: "the VSI would continually under-read", optionC: "the VSI would indicate a descent for a few seconds before returning to zero", optionD: "there would be no change in VSI readings", correctAnswer: "a", explanation: "Cabin static is slightly lower, so switching to alternate momentarily shows a small climb before the differential settles back to zero.", difficulty: "medium" },
  { id: "INS-0504", sectionId: "A.7.1", question: "If, during flight, the static vent in an unpressurised aircraft becomes blocked and the glass covering the VSI is broken, the instrument:", optionA: "will read correctly", optionB: "will read zero under all conditions", optionC: "readings will be reversed", optionD: "will read a continual descent because the pressure in the cockpit is less than external pressure", correctAnswer: "c", explanation: "Breaking the glass feeds cabin static to the case while the capsule holds the delayed trapped static — the sense of the differential reverses, so climb/descent indications are reversed.", difficulty: "hard" },
  { id: "INS-0505", sectionId: "A.7.1", question: "In an instantaneous vertical speed indicator (IVSI) movement of the piston in the accelerometer unit directly controls:", optionA: "the flow of static pressure entering the case of the instrument", optionB: "the flow of delayed static pressure entering the case of the instrument", optionC: "the flow of static pressure to the capsule", optionD: "the VSI needle causing it to move", correctAnswer: "c", explanation: "The accelerometer dashpot pistons momentarily pump static pressure into/out of the capsule, giving an immediate indication before the metering unit takes over.", difficulty: "hard" },
  { id: "INS-0506", sectionId: "A.7.1", question: "In the instantaneous vertical speed indicator (IVSI) the time lag error is virtually eliminated through the use of:", optionA: "a bank of three interconnected capsules", optionB: "a leaf spring which amplifies the capsule's expansion and contraction", optionC: "a small electric motor which drives the needle assembly", optionD: "accelerometer units", correctAnswer: "d", explanation: "The IVSI's accelerometer (dashpot) units give an instant reading, removing the conventional VSI's time lag.", difficulty: "medium" },
  { id: "INS-0507", sectionId: "A.7.1", question: "The use of accelerometers in an instantaneous vertical speed indicator (IVSI) leads directly to an error known as:", optionA: "acceleration error", optionB: "turning error", optionC: "manoeuvre induced error", optionD: "temperature error", correctAnswer: "b", explanation: "In a steep turn the g-load acts on the accelerometer pistons and produces a false climb indication — turning error.", difficulty: "medium" },
  { id: "INS-0508", sectionId: "A.7.1", question: "With reference to the Vertical Speed Indicator (VSI): (1) The effect of changes in temperature during a climb or descent is compensated for by the metering unit. (2) If the static line became blocked during a climb, the instrument will retain the current rate of climb. (3) Temperature compensation is achieved by a bi-metallic strip between the capsule and the linkage system. (4) If the VSI shows an error on the ground, it can be corrected by an adjustment screw on the front of the instrument. (5) Position error may cause the VSI to indicate a momentary climb or descent during the take-off roll.", optionA: "2, 3 and 4 are correct", optionB: "1 and 4 are correct", optionC: "1, 4 and 5 are correct", optionD: "2 and 5 are correct", correctAnswer: "c", explanation: "Temperature is compensated by the metering unit (orifice + capillary), not a bi-metallic strip; a blocked static makes the VSI read zero. Statements 1, 4 and 5 are correct.", difficulty: "hard" },

  // ── Ch6 Gyroscopes → A.7.2 ──
  { id: "INS-0601", sectionId: "A.7.2", question: "The rigidity of a gyro is directly proportional to:", optionA: "rotor speed and inversely proportional to rotor mass", optionB: "gyro inertia and inversely proportional to rotor speed", optionC: "gyro inertia and rotor speed", optionD: "inversely proportional to both rotor speed and rotor mass", correctAnswer: "c", explanation: "Rigidity ∝ rotor speed × moment of inertia (mass concentrated at the rim), and inversely with any applied force.", difficulty: "medium" },
  { id: "INS-0602", sectionId: "A.7.2", question: "In comparison to a low RPM rotor speed a gyro with high rotor speed will:", optionA: "have a higher rate of precession", optionB: "have the same rate of precession", optionC: "possess greater rigidity and an increased rate of precession", optionD: "have a lesser rate of precession", correctAnswer: "d", explanation: "Precession is inversely proportional to rotor speed, so a faster (more rigid) gyro precesses more slowly for a given force.", difficulty: "medium" },
  { id: "INS-0603", sectionId: "A.7.2", question: "The term 'topple' is applied to:", optionA: "the real or apparent wander of a gyro whose axis is in the vertical plane", optionB: "the real wander only of a gyro whose axis is in the horizontal plane", optionC: "the real or apparent wander of a gyro whose axis is in the horizontal plane", optionD: "the real wander of a gyro whose axis is in both the vertical and horizontal planes", correctAnswer: "a", explanation: "Topple is wander (real or apparent) in the vertical plane; drift is wander in the horizontal plane.", difficulty: "medium" },
  { id: "INS-0604", sectionId: "A.7.2", question: "A cause of apparent wander in a gyro is:", optionA: "low rotor RPM", optionB: "the rotation of the earth", optionC: "wear in the gimbal bearings", optionD: "high rotor RPM and a low rate of precession", correctAnswer: "b", explanation: "Apparent wander is the gyro appearing to move because the earth rotates beneath it (real wander comes from mechanical imperfections).", difficulty: "medium" },
  { id: "INS-0605", sectionId: "A.7.2", question: "The term 'drift' refers to:", optionA: "movement of the axis of a gyro in the vertical plane", optionB: "movement of the axis of a gyro which is mounted in either the vertical or horizontal planes", optionC: "movement of the axis of a gyro in the horizontal plane", optionD: "resistance to rate of precession of a gyro due to high rotational speeds", correctAnswer: "c", explanation: "Drift is wander of the gyro axis in the horizontal plane.", difficulty: "medium" },
  { id: "INS-0606", sectionId: "A.7.2", question: "Real wander in a gyro is:", optionA: "caused by the rotation of the earth", optionB: "a result of excessive rotational speed of the gyro rotor", optionC: "applicable only in vertical axis gyros", optionD: "caused by wear in the gimbal bearings", correctAnswer: "d", explanation: "Real wander is caused by random mechanical forces — friction/wear in the bearings and gimbals — precessing the gyro.", difficulty: "medium" },
  { id: "INS-0607", sectionId: "A.7.2", question: "With reference to gyroscopes: (1) An earth gyro has two freedoms and is tied to the vertical by the earth's gravity. (2) A rate gyro has freedom in one plane only. (3) Real wander is caused by the rotation of the earth. (4) A vertical axis gyro will experience maximum topple at the earth's pole. (5) Transport wander occurs on northerly or southerly headings only.", optionA: "1, 3 and 4 are correct", optionB: "1 and 2 are correct", optionC: "1, 2 and 4 are correct", optionD: "1, 4 and 5 are correct", correctAnswer: "b", explanation: "The earth gyro is a 2-freedom tied gyro (1) and the rate gyro has one plane of freedom (2). Real wander is mechanical (not earth rotation); a vertical-axis gyro has no topple at the pole; transport wander occurs on east/west tracks too.", difficulty: "hard" },
  { id: "INS-0608", sectionId: "A.7.2", question: "The term rigidity refers to:", optionA: "the reluctance of a spinning gyro to turn away from its spinning axis", optionB: "the gimbal structure which supports a spinning gyro", optionC: "the resultant effect of a force which occurs 90° from where it was applied", optionD: "the effect of mechanical forces, i.e. wear or bearing friction, on a spinning gyro", correctAnswer: "a", explanation: "Rigidity (gyroscopic inertia) is the gyro's resistance to any change of its spin-axis direction.", difficulty: "medium" },
  { id: "INS-0609", sectionId: "A.7.2", question: "Precession describes:", optionA: "the reluctance of a spinning gyro to turn away from its spinning axis", optionB: "the gimbal structure which supports a spinning gyro", optionC: "the resultant effect of a force which occurs 90° from where it was applied", optionD: "the effect of mechanical forces, i.e. wear or bearing friction, on a spinning gyro", correctAnswer: "c", explanation: "Precession is the gyro's reaction to an applied force appearing 90° round the rotor in the direction of spin.", difficulty: "medium" },
  { id: "INS-0610", sectionId: "A.7.2", question: "If the mass and rate of rotation of a gyro is increased:", optionA: "the rate of precession will increase", optionB: "real wander will increase", optionC: "apparent wander will increase", optionD: "rigidity will increase", correctAnswer: "d", explanation: "More mass (inertia) and higher spin speed both increase rigidity (angular momentum).", difficulty: "medium" },

  // ── Ch7 Directional Gyro → A.7.2 ──
  { id: "INS-0701", sectionId: "A.7.2", question: "The Latitude Rider nut of a DGI compensates for:", optionA: "real wander", optionB: "apparent wander due to the Earth's rotation", optionC: "transport wander", optionD: "topple", correctAnswer: "a", explanation: "The latitude rider (a small weight) applies a deliberate torque to offset the real drift so the DG holds heading; apparent (earth-rate) wander is corrected by re-aligning with the compass.", difficulty: "hard" },
  { id: "INS-0702", sectionId: "A.7.2", question: "The Latitude Rider nut on a DGI is set for zero. If the gyro spins up and away from the pilot and the rider nut is on the right hand side of the gyro axis as seen by the pilot, the adjustment:", optionA: "for latitude 30° S would be to screw the nut inwards from the rotor", optionB: "for latitude 30° S would be to screw the nut outwards from the rotor", optionC: "for latitude 30° N would be to screw the nut outwards from the rotor", optionD: "for any latitude in the north or south hemispheres is always same", correctAnswer: "b", explanation: "To offset the southern-hemisphere apparent drift the correcting torque is set by screwing the rider nut outwards from the rotor for 30° S.", difficulty: "hard" },
  { id: "INS-0703", sectionId: "A.7.2", question: "The Latitude Rider nut of a DGI is set to give zero drift due to the Earth's rotation at 30° S. The gyro readings will:", optionA: "increase when flying North from 30° S", optionB: "increase when flying South from 30° S", optionC: "remain correct when flying East or West along the 30° S parallel", optionD: "decrease when flying East or West along the 30° S parallel", correctAnswer: "b", explanation: "The rider compensates only for 30° S; flying to a higher latitude (further South) increases earth rate, so the applied correction is now too small and the reading drifts (increases).", difficulty: "hard" },
  { id: "INS-0704", sectionId: "A.7.2", question: "The transport wander in the Direction Indicator of an aeroplane flying due west in the Southern Hemisphere is:", optionA: "positive", optionB: "at a maximum", optionC: "zero", optionD: "negative", correctAnswer: "d", explanation: "Flying east/west changes longitude and adds a transport (convergency) component; in the Southern Hemisphere flying west it is negative.", difficulty: "hard" },
  { id: "INS-0705", sectionId: "A.7.2", question: "With regard to the Direction Indicator:", optionA: "the gyroscopic principle used is rigidity in space", optionB: "the instrument uses a vertical axis gyroscope", optionC: "use is made of a rate gyro", optionD: "the instrument relies on controlled precession to provide heading indications", correctAnswer: "a", explanation: "The DG uses a horizontal-axis tied gyro relying on rigidity in space to hold a heading reference.", difficulty: "medium" },
  { id: "INS-0706", sectionId: "A.7.2", question: "The gyroscope of a Direction Indicator has:", optionA: "complete freedom in roll on east and west headings", optionB: "complete freedom in pitch on north and south headings", optionC: "complete freedom in roll on north and south headings", optionD: "limited freedom in pitch on east and west headings", correctAnswer: "c", explanation: "The DG is a horizontal-axis tied gyro with two gimbals; the exam answer is that it has complete freedom in roll on north/south headings.", difficulty: "hard" },
  { id: "INS-0707", sectionId: "A.7.2", question: "In the case of the Direction Indicator:", optionA: "real wander is corrected through adjustment of the latitude rider nut", optionB: "real wander can only be corrected by manually re-setting the instrument with the magnetic compass", optionC: "apparent wander is caused by gimbal bearing friction and turbulence", optionD: "transport wander on northerly or southerly headings can be corrected by latitude rider nut adjustment", correctAnswer: "b", explanation: "Real (mechanical) wander is random, so it can only be removed by periodically re-synchronising the DG to the magnetic compass.", difficulty: "medium" },
  { id: "INS-0708", sectionId: "A.7.2", question: "In the Southern Hemisphere, the readings of a Direction Indicator of an aircraft:", optionA: "flying in a westerly direction will increase because of transport wander", optionB: "flying in a westerly direction will decrease because of real wander", optionC: "flying in a westerly direction will decrease because of transport wander", optionD: "flying in an easterly direction will decrease because of transport wander", correctAnswer: "c", explanation: "Southern-hemisphere transport wander flying west is negative, so the DG readings decrease.", difficulty: "hard" },
  { id: "INS-0709", sectionId: "A.7.2", question: "With reference to the air driven Direction Indicator:", optionA: "the gyro spins at about 15 000 RPM and has freedom of movement of about 90 degrees either side of the vertical plane", optionB: "the gyro spins at about 10 000 RPM and has freedom of movement of about 90 degrees either side of the vertical plane", optionC: "the gyro spins at about 18 000 RPM and has freedom of movement of about 55 degrees either side of the vertical plane", optionD: "the gyro spins at about 10 000 RPM and has freedom of movement of about 55 degrees either side of the vertical plane", correctAnswer: "d", explanation: "The air-driven DG rotor turns at roughly 10 000 RPM with about ±55° of gimbal freedom.", difficulty: "medium" },
  { id: "INS-0710", sectionId: "A.7.2", question: "With reference to the air driven Direction Indicator: (1) The instrument utilises a vertical axis gyro. (2) The air jets are attached to the outer gimbal. (3) The gyro has freedom of movement of about 55° either side of the vertical plane. (4) The incorrect change in heading caused by gimballing error will remain until the gyro is re-aligned with the magnetic compass. (5) Air jets are used to maintain the spin axis of the gyro in the horizontal plane.", optionA: "2, 3 and 5 are correct", optionB: "1, 3 and 4 are correct", optionC: "1, 3 and 5 are correct", optionD: "2, 4 and 5 are correct", correctAnswer: "a", explanation: "The DG uses a horizontal-axis gyro; the air jets on the outer gimbal (2) give ±55° freedom (3) and maintain the spin axis horizontal (5).", difficulty: "hard" },
  { id: "INS-0711", sectionId: "A.7.2", question: "With reference to the air driven Direction Indicator: (1) The maximum error caused by the earth's rotation is 15° in 24 hours. (2) Gimballing error is caused by bank or pitch. (3) Apparent wander is maximum at the equator. (4) The drift at 30° latitude is 7.5°. (5) Air jets are used to maintain the gyro rotor in the aircraft's vertical.", optionA: "2, 3 and 4 are correct", optionB: "1 and 5 are correct", optionC: "2, 4 and 5 are correct", optionD: "3 and 4 are correct", correctAnswer: "c", explanation: "Gimballing error comes from bank/pitch (2); drift at 30° = 15° × sin30° = 7.5° (4); the jets keep the rotor axis horizontal in the aircraft (5).", difficulty: "hard" },

  // ── Ch8 Artificial Horizon → A.7.2 ──
  { id: "INS-0801", sectionId: "A.7.2", question: "The approximate point in a normal co-ordinated turn, at which the turn error in a suction driven Artificial Horizon is at its maximum is at:", optionA: "90 degrees", optionB: "180 degrees", optionC: "270 degrees", optionD: "360 degrees", correctAnswer: "b", explanation: "The combined pendulous + erection turn errors build to a maximum at about 180° of turn, then reduce to zero by 360°.", difficulty: "hard" },
  { id: "INS-0802", sectionId: "A.7.2", question: "When an aircraft is rapidly accelerated in straight and level flight, or at take-off, the air-driven artificial horizon will indicate:", optionA: "a straight descent", optionB: "a climb and left bank", optionC: "a climb and right bank", optionD: "a descent and right bank", correctAnswer: "c", explanation: "Acceleration produces both a pendulous and an erection error that combine to show a false climb and right bank.", difficulty: "hard" },
  { id: "INS-0803", sectionId: "A.7.2", question: "The air driven Artificial Horizon erection error is caused by:", optionA: "displacement of the fore and aft vanes", optionB: "inertia fully closing the left hand port vane and fully opening the right hand port vane", optionC: "wear and tear of the gimbal bearings", optionD: "inertia fully closing the right hand port vane and fully opening the left hand port vane", correctAnswer: "b", explanation: "Under acceleration inertia moves the pendulous vanes — closing the left and opening the right port — unbalancing the exhaust and precessing the gyro.", difficulty: "hard" },
  { id: "INS-0804", sectionId: "A.7.2", question: "With reference to electrically operated Artificial Horizons. Gyro wander about the pitch axis is controlled by:", optionA: "a mercury levelling switch mounted at right angles to the pitch axis inducing a torque about the roll axis", optionB: "a mercury levelling switch mounted in line with the pitch axis inducing a torque about the pitch axis", optionC: "a mercury levelling switch mounted at right angles to the roll axis inducing a torque about the pitch axis", optionD: "a mercury levelling switch mounted in line with the pitch axis inducing a torque about the roll axis", correctAnswer: "a", explanation: "A mercury switch on the roll axis (i.e. at right angles to the pitch axis) senses pitch tilt and drives a torque motor to erect the gyro — precession then corrects the pitch axis.", difficulty: "hard" },
  { id: "INS-0805", sectionId: "A.7.2", question: "The spin axis of the gyroscope used in the Artificial Horizon is maintained in the vertical relative to the earth by:", optionA: "gyroscopic precession", optionB: "gyroscopic rigidity", optionC: "gravity", optionD: "mounting the outer gimbal along the aircraft's fore and aft axis", correctAnswer: "b", explanation: "The AH is an earth (tied) gyro; its rigidity holds the spin axis vertical, with the erection system slowly tying it to the true vertical.", difficulty: "medium" },
  { id: "INS-0806", sectionId: "A.7.2", question: "During changes in pitch the spin axis of the gyroscope in the Artificial Horizon:", optionA: "remains parallel to the aircraft's lateral axis", optionB: "remains parallel to the aircraft's longitudinal axis", optionC: "remains in the vertical relative to the earth", optionD: "remains in the vertical relative to the aircraft", correctAnswer: "c", explanation: "The AH spin axis stays vertical relative to the earth while the aircraft pitches and rolls about it.", difficulty: "medium" },
  { id: "INS-0807", sectionId: "A.7.2", question: "When an aircraft is decelerated in straight and level flight, the air-driven artificial horizon will indicate:", optionA: "a straight climb", optionB: "a climb and left bank", optionC: "a descent and right bank", optionD: "a descent and left bank", correctAnswer: "d", explanation: "Deceleration produces the opposite of the acceleration error — a false descent and left bank.", difficulty: "hard" },
  { id: "INS-0808", sectionId: "A.7.2", question: "The incorrect nose up, or climb attitude, shown on the air-driven AH during take-off is caused by:", optionA: "the effect of inertia which closes the left vane and opens the right vane", optionB: "the effect of inertia which closes the right vane and opens the left vane", optionC: "the effect of inertia on the base of the unit", optionD: "excessively high rotor speed", correctAnswer: "a", explanation: "Acceleration inertia on the pendulous vanes (closing left, opening right port) precesses the gyro to show a false climb.", difficulty: "hard" },
  { id: "INS-0809", sectionId: "A.7.2", question: "The freedom of movement of the outer gimbal of an artificial horizon is about:", optionA: "the lateral, or pitch, axis", optionB: "the aircraft's vertical axis", optionC: "the longitudinal, or roll, axis", optionD: "both the lateral and longitudinal axes", correctAnswer: "c", explanation: "The outer gimbal pivots on the fore-and-aft (longitudinal) axis, so its freedom of movement provides the roll indication.", difficulty: "medium" },
  { id: "INS-0810", sectionId: "A.7.2", question: "The freedom of movement of the inner gimbal of an artificial horizon is about:", optionA: "both the lateral and longitudinal axes", optionB: "the aircraft's vertical axis", optionC: "the longitudinal, or roll, axis", optionD: "the lateral, or pitch, axis", correctAnswer: "d", explanation: "The inner gimbal pivots on the lateral (athwartships) axis, providing the pitch indication.", difficulty: "medium" },
  { id: "INS-0811", sectionId: "A.7.2", question: "The type of gyro used in an Artificial Horizon is:", optionA: "a Tied gyro", optionB: "an Earth gyro", optionC: "a Rate gyro", optionD: "a space gyro", correctAnswer: "b", explanation: "The AH uses an earth gyro (a tied gyro whose axis is tied to the vertical by gravity/erection).", difficulty: "medium" },
  { id: "INS-0812", sectionId: "A.7.2", question: "With reference to the artificial horizon: (1) The horizon bar is pivoted on the outer gimbal and moved by a guide pin on the inner gimbal. (2) The vertical axis gyro is mounted within 2 gimbals. (3) Movement of the inner gimbal provides the aircraft's roll indications. (4) The inner gimbal has its pivot points about the longitudinal axis. (5) During a bank, the rotor remains in the true vertical.", optionA: "1, 4 and 5 are correct", optionB: "2, 3 and 4 are correct", optionC: "3 and 5 are correct", optionD: "1, 2 and 5 are correct", correctAnswer: "d", explanation: "The horizon bar is guided by a pin between the gimbals (1); the vertical-axis gyro sits in two gimbals (2); the rotor stays vertical during a bank (5). The inner gimbal provides pitch (not roll) and pivots on the lateral axis.", difficulty: "hard" },

  // ── Ch9 Turn & Slip Indicator → A.7.2 ──
  { id: "INS-0901", sectionId: "A.7.2", question: "The correct indications obtained from the Turn and Slip indicator during taxi are:", optionA: "the needle and ball should move freely in the direction of the turn", optionB: "the ball moves opposite to the turn and the needle deflects in the direction of the turn", optionC: "the ball deflects opposite to the turn and the needle remains central", optionD: "the ball deflects into the turn and the needle deflects in the opposite direction of the turn", correctAnswer: "b", explanation: "Taxiing round a turn: the needle shows the turn (correct sense) while the ball skids to the outside (opposite the turn).", difficulty: "medium" },
  { id: "INS-0902", sectionId: "A.7.2", question: "The approximate angle of bank for a rate one turn at 110 knots is:", optionA: "18 degrees", optionB: "25 degrees", optionC: "30 degrees", optionD: "11 degrees", correctAnswer: "a", explanation: "Bank ≈ (10% of TAS) + 7 = 11 + 7 = 18°.", difficulty: "medium" },
  { id: "INS-0903", sectionId: "A.7.2", question: "If the rotational speed of the Turn and Slip gyro rotor is below the calibrated speed:", optionA: "the Turn indicator over-reads", optionB: "both the Turn indicator and the Slip indicator under-read", optionC: "the turn indicator is unaffected because the springs are calibrated to compensate for low RPM", optionD: "the Turn indicator under-reads, the slip indicator is not affected", correctAnswer: "d", explanation: "A slow rotor precesses less, so the turn needle under-reads; the ball (slip) is a purely mechanical/gravity device and is unaffected.", difficulty: "medium" },
  { id: "INS-0904", sectionId: "A.7.2", question: "The angle of tilt of a rate-gyro in a turn and slip indicator is caused by:", optionA: "the spring tension opposing primary precession", optionB: "the secondary precession caused by spring tension, balancing primary precession", optionC: "the gimbal axis being set at 30° to the horizontal axis of the aircraft", optionD: "high RPM and a low rate of precession", correctAnswer: "b", explanation: "The turn produces primary precession which tilts the rotor; spring tension produces a secondary precession that balances it, and the equilibrium tilt indicates the rate of turn.", difficulty: "hard" },
  { id: "INS-0905", sectionId: "A.7.2", question: "A warning flag appears on an electrical Turn Co-ordinator, this means that:", optionA: "there is a total instrument failure", optionB: "the vacuum system has failed", optionC: "the Turn indicator has failed but the Slip indicator is serviceable", optionD: "the Slip indicator has failed but the Turn indicator is serviceable", correctAnswer: "c", explanation: "The flag warns of electrical (gyro) failure — the turn function is lost, but the mechanical ball (slip) still works.", difficulty: "medium" },
  { id: "INS-0906", sectionId: "A.7.2", question: "The type of gyro used in the air-driven turn indicator is a:", optionA: "vertical axis rate gyro having freedom of movement in two planes", optionB: "horizontal axis earth gyro having freedom of movement in one plane only", optionC: "space gyro having freedom of movement in one plane only", optionD: "horizontal axis rate gyro having freedom of movement in one plane only", correctAnswer: "d", explanation: "The turn indicator uses a horizontal-axis rate gyro with one plane of freedom (about the roll axis).", difficulty: "medium" },
  { id: "INS-0907", sectionId: "A.7.2", question: "In relation to the Artificial Horizon and the Directional Gyro, the gyro in a turn indicator:", optionA: "operates at a higher RPM because high rigidity is required", optionB: "operates at the same RPM but has a smaller mass which aids precession", optionC: "operates at a lower RPM because high rigidity is not required", optionD: "operates at a lower RPM but has a greater mass which provides greater rigidity", correctAnswer: "c", explanation: "The turn indicator MEASURES precession, so it deliberately runs at a lower RPM (~9000) — low rigidity lets it precess with the turn.", difficulty: "medium" },
  { id: "INS-0908", sectionId: "A.7.2", question: "With reference to the Turn Co-ordinator: (1) The gyro has freedom in two planes. (2) Because there is only one gimbal the gyro will not topple. (3) The instrument employs a horizontal axis rate gyro which spins down and towards the pilot. (4) Spring tension creates a secondary precession which is equal to the rate of turn. (5) The gimbal is inclined to the aircraft's longitudinal axis by 30° in order to make the gyro sensitive to movements about the roll axis.", optionA: "2, 4 and 5 are correct", optionB: "1, 2 and 5 are correct", optionC: "3, 4 and 5 are correct", optionD: "1 and 3 are correct", correctAnswer: "a", explanation: "The single-gimbal rate gyro cannot topple (2); spring secondary precession balances the turn rate (4); the 30° inclined gimbal makes it sensitive to roll as well as yaw (5).", difficulty: "hard" },

  // ── Ch10 Flight Director System → A.7.3 ──
  { id: "INS-1001", sectionId: "A.7.3", question: "On a cross pointer ADI the horizontal and vertical bars appear up and to the right of the miniature aircraft. The pilot should:", optionA: "decrease the pitch angle and turn right", optionB: "increase the pitch angle and turn right", optionC: "increase the pitch angle and turn left", optionD: "fly away from both needles", correctAnswer: "b", explanation: "Fly the aircraft symbol into the command bars: bars up = pitch up (increase pitch), bars right = turn right.", difficulty: "medium" },
  { id: "INS-1002", sectionId: "A.7.3", question: "With APPR or GS selected on a Flight Director Controller:", optionA: "the pitch and roll bars are automatically disconnected", optionB: "the roll bar is disconnected but the pitch command bar can be used to fly the glideslope", optionC: "the roll and pitch command bars will indicate localiser and glidepath interception requirements", optionD: "the pitch bar is disconnected but the roll command bar can be used to fly the localiser", correctAnswer: "c", explanation: "In approach/GS mode both command bars are live, commanding localiser (roll) and glidepath (pitch) capture and tracking.", difficulty: "medium" },
  { id: "INS-1003", sectionId: "A.7.3", question: "A flight-director command display shows the pitch bar low and the roll bar deflected to the left of the aircraft symbol. This means:", optionA: "fly down and left", optionB: "fly up and left", optionC: "fly left only", optionD: "fly up and right", correctAnswer: "a", explanation: "Command bars are flown TO: a low pitch bar commands nose-down (fly down) and a left roll bar commands a left turn — fly down and left.", difficulty: "medium" },
  { id: "INS-1004", sectionId: "A.7.3", question: "A Horizontal Situation Indicator (HSI):", optionA: "must be re-set against the aircraft's magnetic compass every 15 minutes", optionB: "provides pitch and roll information as well as ILS glide slope and localiser data", optionC: "has to be manually aligned with the aircraft's magnetic compass after start-up", optionD: "receives heading information from a remote gyro compass", correctAnswer: "d", explanation: "The HSI compass card is slaved to a remote (gyro-stabilised) magnetic heading source, so it needs no manual synchronising.", difficulty: "medium" },
  { id: "INS-1005", sectionId: "A.7.3", question: "The aircraft symbol on an HSI:", optionA: "can be turned by the course selection knob to the required heading", optionB: "is used to select the required VOR radial to intercept", optionC: "can be set to the localiser bearing as a reminder", optionD: "is fixed permanently in line with the aircraft's fore-aft axis", correctAnswer: "a", explanation: "Per the book's answer key, option (a) is marked correct; note that on a conventional HSI the small aircraft symbol is fixed and the COURSE pointer is what the course knob turns — worth verifying against your syllabus.", difficulty: "medium" },
  { id: "INS-1006", sectionId: "A.7.3", question: "On a 5 dot HSI with VOR selected and the course deviation bar showing 2 dots left, the aircraft will be:", optionA: "4 nm to the right of the selected radial", optionB: "4° to the right of the selected radial", optionC: "1° to the right of the selected radial", optionD: "4° to the left of the selected radial", correctAnswer: "b", explanation: "Each dot ≈ 2°, so 2 dots = 4°; a left-deflected bar means the radial is to the left, i.e. the aircraft is 4° to the right of it.", difficulty: "hard" },
  { id: "INS-1007", sectionId: "A.7.3", question: "With reference to the Flight Director: (1) When altitude hold is selected, any deviation will cause pitch commands to be generated. (2) The flight director computer generates pitch, roll and yaw commands. (3) When GA is selected on the MCP a go-around is initiated following a missed approach. (4) A red flag showing GYRO will appear on the ADI if attitude information is lost. (5) The aircraft symbol on the face of the HSI rotates with the compass card.", optionA: "2 and 4 are correct", optionB: "1, 2 and 5 are correct", optionC: "1, 3 and 4 are correct", optionD: "3, 4 and 5 are correct", correctAnswer: "c", explanation: "Altitude hold generates pitch commands on deviation (1); GA arms the go-around (3); a lost-attitude GYRO flag shows on the ADI (4). The FD generates pitch and roll (not yaw) and the HSI aircraft symbol is fixed.", difficulty: "hard" },

  // ── Ch11 Electronic Flight Information System (EFIS) → A.7.3 ──
  { id: "INS-1101", sectionId: "A.7.3", question: "During an ILS approach the flight crew are alerted that the aircraft is approaching the decision height (DH), by an aural alert which is activated at DH:", optionA: "+100 feet", optionB: "+150 feet", optionC: "+50 feet", optionD: "+75 feet", correctAnswer: "c", explanation: "An aural chime begins about 50 ft above the selected decision height, increasing in rate until DH is reached.", difficulty: "medium" },
  { id: "INS-1102", sectionId: "A.7.3", question: "When operated in the MAP mode, the compass rose on the EHSI is automatically referenced to magnetic north when operating:", optionA: "between latitudes 73°N and 60°S", optionB: "up to 75° either side of the equator", optionC: "between latitudes 60°N and 73°S", optionD: "above latitude 73°N", correctAnswer: "a", explanation: "The rose auto-references magnetic north between 73°N and 60°S; outside those latitudes it must be referenced to true north.", difficulty: "hard" },
  { id: "INS-1103", sectionId: "A.7.3", question: "The information that is displayed on the Captain's and First Officer's displays is checked for agreement by:", optionA: "the MCP", optionB: "third SG", optionC: "pressing a control button on the Captain's display", optionD: "the ICU", correctAnswer: "d", explanation: "The Instrument Comparator Unit (ICU) monitors the two pilots' displays for pitch/roll/heading/track disagreement and raises a master warning.", difficulty: "medium" },
  { id: "INS-1104", sectionId: "A.7.3", question: "On the EADI, the radar altitude display is blank:", optionA: "below 1500 ft", optionB: "above 2500 ft", optionC: "above 1500 ft", optionD: "above 1000 ft", correctAnswer: "b", explanation: "Radio altitude appears below 2500 ft (digital 2500–1000 ft, analogue ring below 1000 ft) and is blank above 2500 ft.", difficulty: "medium" },
  { id: "INS-1105", sectionId: "A.7.3", question: "The colour used for EFIS command information is usually:", optionA: "red", optionB: "amber", optionC: "white", optionD: "magenta", correctAnswer: "d", explanation: "Magenta (pink) is used for command information, pointers and 'fly-to' symbols on EFIS displays.", difficulty: "medium" },
  { id: "INS-1106", sectionId: "A.7.3", question: "The radio altitude readout on the EADI changes from a digital readout to a white circle when the aircraft is below:", optionA: "1000 ft", optionB: "1500 ft", optionC: "2500 ft", optionD: "500 ft", correctAnswer: "a", explanation: "Below 1000 ft the digital radio-altitude is replaced by a white analogue ring scale (with digital readout).", difficulty: "medium" },
  { id: "INS-1107", sectionId: "A.7.3", question: "On reaching DH, the marker on the radio altitude changes from:", optionA: "white to magenta", optionB: "magenta to amber", optionC: "magenta to green", optionD: "white to red", correctAnswer: "b", explanation: "At decision height the ring scale changes white→amber and the DH marker changes magenta→amber (and flashes).", difficulty: "medium" },
  { id: "INS-1108", sectionId: "A.7.3", question: "A compression mode is incorporated in EFIS so that:", optionA: "weather radar information can be simultaneously portrayed on both Captain and First Officer EHSI screens", optionB: "the information that is displayed on the Captain's and First Officer's displays can be checked for agreement", optionC: "if an EADI fails modified information will be automatically displayed on the same crew member's HSI", optionD: "when operating an EHSI in expanded ILS mode, weather radar information can be portrayed", correctAnswer: "c", explanation: "Compression (composite) mode squeezes the failed screen's information onto the remaining serviceable screen for that crew member.", difficulty: "medium" },
  { id: "INS-1109", sectionId: "A.7.3", question: "If the symbol generator on the Captain's side fails:", optionA: "the ICU will automatically transfer data from the First Officer's symbol generator", optionB: "the compression mode automatically provides data from the First Officer's screens", optionC: "the third symbol generator can be activated by a pilot controlled switch to provide data to the Captain's screens", optionD: "the compression mode automatically provides data from the First Officer's display", correctAnswer: "c", explanation: "A standby (third) symbol generator can be selected by the pilot to drive either side's displays if its own SG fails.", difficulty: "medium" },
  { id: "INS-1110", sectionId: "A.7.3", question: "The primary source of heading data for the Captain's EHSI is:", optionA: "the centre IRS", optionB: "the centre symbol generator", optionC: "the mode selector panel", optionD: "the left IRS", correctAnswer: "d", explanation: "The left IRS supplies the Captain's EHSI (right IRS the First Officer's), with the centre IRS as an alternate.", difficulty: "medium" },
  { id: "INS-1111", sectionId: "A.7.3", question: "The selection of the decision height (DH) is made:", optionA: "only by the Captain's control panel", optionB: "on the ADI section of the Mode Control Panel", optionC: "on the HSI section of the Mode Control Panel", optionD: "only by the Flight Management Computer", correctAnswer: "b", explanation: "DH is preset with the DH REF control in the ADI/EADI section of each pilot's Mode Control Panel.", difficulty: "medium" },
  { id: "INS-1112", sectionId: "A.7.3", question: "EFIS weather (WXR) displays:", optionA: "are selected by the EHSI section of the MCP and can be displayed simultaneously on the Captain's and First Officer's EHSI", optionB: "can be used on the FULL VOR mode of the HSI", optionC: "are selected by the ADI section of the MCP and can be displayed simultaneously on the Captain's and First Officer's EHSI", optionD: "can only be used in the PLAN mode of the EHSI", correctAnswer: "a", explanation: "WXR is switched on in the EHSI section of the MCP and can appear on both pilots' EHSIs (in map/expanded modes, not full VOR/ILS or plan).", difficulty: "medium" },
  { id: "INS-1113", sectionId: "A.7.3", question: "With reference to the Electronic Flight Information System: (1) The ICU monitors the Captain's and First Officer's displays for disagreement in pitch and roll, heading and track. (2) Weather radar data is displayed on the HSI in white, green, amber and red. (3) Weather radar may be displayed on the HSI when using the Map, Expanded ILS and Expanded VOR settings. (4) The colour magenta is used on the HSI to display command information, pointers, symbols and fly to. (5) Above 2500 ft, the radio altitude display on the EADI is displayed in white.", optionA: "2, 4 and 5 are correct", optionB: "1, 2 and 5 are correct", optionC: "1, 2, 3 and 4 are correct", optionD: "1, 3 and 4 are correct", correctAnswer: "d", explanation: "The ICU monitors for pitch/roll/heading/track disagreement (1); WXR shows in map and expanded VOR/ILS (3); magenta is command information (4). WXR colours are cyan/green/amber/red (not white), and above 2500 ft the radio-alt display is blank.", difficulty: "hard" },
  { id: "INS-1114", sectionId: "A.7.3", question: "During flight, the localiser deviation pointer sense will reverse if the aeroplane's track is:", optionA: "more than 45° from the selected ILS course", optionB: "more than 20 nm from the selected front ILS course", optionC: "more than 90° from the selected ILS course", optionD: "more than 60° from the selected ILS course", correctAnswer: "c", explanation: "Beyond 90° from the selected course the localiser pointer sense reverses so it remains usable on back-course approaches.", difficulty: "medium" },

  // ── Ch12 Automatic Pilot → A.7.6 ──
  { id: "INS-1201", sectionId: "A.7.6", question: "A single axis autopilot is one which:", optionA: "provides control about the lateral, or pitch, axis", optionB: "provides control about the longitudinal, or roll, axis", optionC: "provides control about the normal, or vertical, axis", optionD: "can be used to climb an aeroplane at pre-selected pitch attitudes", correctAnswer: "b", explanation: "A single-axis autopilot controls only roll (about the longitudinal axis) — a wing leveller.", difficulty: "medium" },
  { id: "INS-1202", sectionId: "A.7.6", question: "A wing leveller is an example of:", optionA: "a single axis autopilot", optionB: "a two axis autopilot", optionC: "a three axis autopilot", optionD: "the type of autopilot which controls an aeroplane's heading using aileron and rudder inputs", correctAnswer: "a", explanation: "A wing leveller controls roll only, so it is a single-axis autopilot.", difficulty: "easy" },
  { id: "INS-1203", sectionId: "A.7.6", question: "When CWS is selected on the Mode Control Panel (MCP):", optionA: "the autopilot is disconnected and the flight crew can control the aeroplane manually", optionB: "a thumb switch disconnects the autopilot to allow manual control of the aeroplane", optionC: "the autopilot retains pitch control but the crew can operate the ailerons and rudder manually", optionD: "the flight crew can control the aeroplane in pitch and roll without disconnecting the autopilot", correctAnswer: "d", explanation: "Control Wheel Steering lets the crew manoeuvre in pitch and roll while the autopilot stays engaged, resuming when the controls are released.", difficulty: "medium" },
  { id: "INS-1204", sectionId: "A.7.6", question: "Touch Control Steering means:", optionA: "the flight crew can control the aeroplane in pitch and roll without disconnecting the autopilot", optionB: "a thumb switch disconnects the autopilot to allow manual control of the aeroplane", optionC: "the flight crew can make small heading corrections using a heading control bug", optionD: "the autopilot retains control in roll and yaw but the pilot can manually change the pitch", correctAnswer: "a", explanation: "Touch Control Steering allows manual pitch/roll inputs with the autopilot still engaged (it re-holds the new attitude on release).", difficulty: "medium" },
  { id: "INS-1205", sectionId: "A.7.6", question: "An Inner loop is considered to be a closed loop because of:", optionA: "the use of rate gyros", optionB: "the use of displacement gyros", optionC: "pilot controlled inputs", optionD: "the inclusion of feedback in the system", correctAnswer: "d", explanation: "The inner (stabilisation) loop is closed because the servo output is fed back and compared, keeping the aircraft at the demanded attitude.", difficulty: "medium" },
  { id: "INS-1206", sectionId: "A.7.6", question: "When 'Altitude Capture' is selected on the autopilot:", optionA: "an altitude capture warning light is activated on reaching the altitude", optionB: "an altitude capture warning light is activated some 300ft - 200ft prior to reaching the altitude", optionC: "an altitude capture warning light is activated some 1000ft - 700ft prior to reaching the altitude", optionD: "an altitude capture warning light is activated some 1500ft - 800ft prior to reaching the altitude", correctAnswer: "c", explanation: "Altitude capture arms and annunciates roughly 1000–700 ft before the selected altitude, then levels the aircraft off.", difficulty: "medium" },

  // ── Ch13 Terrestrial Magnetism → A.7.7 ──
  { id: "INS-1301", sectionId: "A.7.7", question: "An agonic line joins places of:", optionA: "equal magnetic variation", optionB: "zero magnetic variation", optionC: "equal horizontal force H", optionD: "equal magnetic dip", correctAnswer: "b", explanation: "An agonic line joins places of zero variation (isogonals join places of equal variation).", difficulty: "medium" },
  { id: "INS-1302", sectionId: "A.7.7", question: "Variation should be:", optionA: "added to a true bearing when Magnetic North is to the West of True North", optionB: "added to a true bearing when Magnetic North is to the East of True North", optionC: "subtracted from a true bearing when Magnetic North is to the West of True North", optionD: "subtracted from a magnetic bearing to obtain a true bearing when Magnetic North is to the East of True North", correctAnswer: "a", explanation: "Variation West → Magnetic Best: to convert a true bearing to magnetic you ADD westerly variation.", difficulty: "medium" },
  { id: "INS-1303", sectionId: "A.7.7", question: "At high latitudes:", optionA: "component Z is small and component H is large", optionB: "both component Z and component H are small", optionC: "both component Z and component H are average", optionD: "component Z is large and component H is small", correctAnswer: "d", explanation: "Near the magnetic poles the field is nearly vertical: the vertical component Z is large and the horizontal component H (which gives the compass its directive force) is small.", difficulty: "medium" },
  { id: "INS-1304", sectionId: "A.7.7", question: "An isodyne is:", optionA: "is a line joining places of equal vertical force (Z)", optionB: "is a line joining places of zero Magnetic Dip", optionC: "is a line joining places of equal horizontal force (H)", optionD: "is a line joining places of equal Magnetic Dip", correctAnswer: "c", explanation: "Isodynes join places of equal horizontal force H.", difficulty: "medium" },
  { id: "INS-1305", sectionId: "A.7.7", question: "With reference to hard and soft iron: (1) Hard iron is difficult to magnetise. (2) Soft iron is difficult to magnetise. (3) Once magnetised, soft iron retains its magnetism permanently. (4) Once magnetised, hard iron retains its magnetism permanently. (5) Hard iron is easy to magnetise. (6) When magnetised within a solenoid, soft iron will retain its magnetism permanently.", optionA: "only 1, 3 and 6 are correct", optionB: "only 4 and 5 are correct", optionC: "only 1 and 4 are correct", optionD: "only 1, 5 and 6 are correct", correctAnswer: "c", explanation: "Hard iron is difficult to magnetise but retains it permanently (1 and 4); soft iron magnetises easily but loses it quickly.", difficulty: "medium" },
  { id: "INS-1306", sectionId: "A.7.7", question: "The secular change in the earth's magnetic variation is caused by:", optionA: "the rotation of the moon around the earth", optionB: "the westerly movement of the magnetic poles around the geographic poles", optionC: "the 11 year cycle of sun spot activity", optionD: "the earth's movement around the sun", correctAnswer: "b", explanation: "Secular change is the slow (~960-year) westerly drift of the magnetic poles around the geographic poles.", difficulty: "medium" },
  { id: "INS-1307", sectionId: "A.7.7", question: "The directive force:", optionA: "refers to component Z of the earth's magnetic field and is greatest at the magnetic poles", optionB: "refers to component T of the earth's magnetic field and is greatest at the magnetic equator", optionC: "refers to component H of the earth's magnetic field and is greatest at the magnetic poles", optionD: "refers to component H of the earth's magnetic field and is greatest at the magnetic equator", correctAnswer: "d", explanation: "The directive force is the horizontal component H that aligns the compass; it is greatest at the magnetic equator and zero at the poles.", difficulty: "medium" },
  { id: "INS-1308", sectionId: "A.7.7", question: "A line which joins places having equal magnetic dip is called:", optionA: "an isoclinal", optionB: "an aclinic line", optionC: "isodynes", optionD: "an agonic line", correctAnswer: "a", explanation: "Isoclinals join places of equal dip; the aclinic line joins places of zero dip (the magnetic equator).", difficulty: "medium" },
  { id: "INS-1309", sectionId: "A.7.7", question: "With reference to magnetic principles: (1) The angle of dip increases away from the magnetic equator. (2) The horizontal component of the earth's magnetic field (H) increases with an increase in magnetic latitude. (3) The angle of dip is inversely proportional to H. (4) Lines of magnetic flux will not cross one another. (5) The value of H is proportional to Z.", optionA: "1, 2 and 5 are correct", optionB: "2, 3 and 4 are correct", optionC: "1, 3 and 4 are correct", optionD: "1, 3 and 5 are correct", correctAnswer: "c", explanation: "Dip increases toward the poles (1); dip is inversely related to H (3); flux lines never cross (4). H decreases (not increases) with latitude, and H is inversely related to Z.", difficulty: "hard" },
  { id: "INS-1310", sectionId: "A.7.7", question: "The discrepancy between magnetic bearings and compass bearings is primarily caused by:", optionA: "magnetic variation", optionB: "deviation", optionC: "friction in the bearings of the compass", optionD: "magnetic dip", correctAnswer: "b", explanation: "Deviation — the aircraft's own magnetism deflecting the compass — is the difference between magnetic and compass bearings (variation is the true-to-magnetic difference).", difficulty: "medium" },

  // ── Ch14 Aircraft Magnetism → A.7.7 ──
  { id: "INS-1401", sectionId: "A.7.7", question: "During the correcting swing of a direct reading magnetic compass the following readings were noted — Magnetic/Compass: 359/001, 090/088, 181/179, 269/273. The value of coefficient A is:", optionA: "-0.5°", optionB: "+0.5°", optionC: "-2°", optionD: "+2°", correctAnswer: "a", explanation: "Deviations are −2, +2, +2, −4; coefficient A = (sum)/4 = (−2)/4 = −0.5°.", difficulty: "hard" },
  { id: "INS-1402", sectionId: "A.7.7", question: "The following Coefficients apply to a particular compass system: Coefficient A +2°, Coefficient B +4°, Coefficient C -3°. The deviation expected on heading 135° (C) is:", optionA: "+6.95°", optionB: "+2.7°", optionC: "-2.7°", optionD: "-1.5°", correctAnswer: "a", explanation: "Dev = A + B·sinH + C·cosH = 2 + 4·sin135 − 3·cos135 = 2 + 2.83 + 2.12 = +6.95°.", difficulty: "hard" },
  { id: "INS-1403", sectionId: "A.7.7", question: "With reference to aircraft magnetism: (1) The effect of HHI deviation is inversely proportional to the value of H. (2) The value of coefficient A is only valid on cardinal and quadrantal headings. (3) Coefficient B is calculated using the formula: (dev E − dev W) ÷ 2. (4) Compass deviation caused by parameter Q which is maximum on North and South is referred to as coefficient C. (5) The horizontal force of the earth's magnetic field increases with an increase in magnetic latitude.", optionA: "all of the above statements are correct", optionB: "2, 4 and 5 are correct", optionC: "1, 2 and 3 are correct", optionD: "1, 3 and 4 are correct", correctAnswer: "d", explanation: "Horizontal-hard-iron deviation ∝ 1/H (1); coefficient B = (dev E − dev W)/2 (3); coefficient C (parameter Q) is maximum on N/S (4). Coefficient A applies on all headings, and H decreases with magnetic latitude.", difficulty: "hard" },
  { id: "INS-1404", sectionId: "A.7.7", question: "A compass system has Coefficient A +1° and Coefficient B +3°. The deviation on heading 230° (C) is -3°. The value of Coefficient C is:", optionA: "+2.65°", optionB: "-9.82°", optionC: "-3.71°", optionD: "+1.85°", correctAnswer: "a", explanation: "−3 = 1 + 3·sin230 + C·cos230 = 1 − 2.30 − 0.643C ⇒ C ≈ +2.65°.", difficulty: "hard" },
  { id: "INS-1405", sectionId: "A.7.7", question: "An aircraft deviation card reads — For Magnetic / Steer Compass: 225°/218°, 270°/272°. The compass heading to steer to maintain a heading of 255° (M) is:", optionA: "256° (C)", optionB: "255° (C)", optionC: "253° (C)", optionD: "254° (C)", correctAnswer: "d", explanation: "Deviation is +7 at 225 and −2 at 270; interpolating to 255° gives dev ≈ +1, so compass = 255 − 1 = 254° (C).", difficulty: "hard" },
  { id: "INS-1406", sectionId: "A.7.7", question: "A compass system has Coefficient A -2°, B -4°, C +3°. The required track is 022° (T), drift 7° left, Variation 16° W. The compass heading to steer will be:", optionA: "042° (C)", optionB: "045° (C)", optionC: "047.7° (C)", optionD: "046° (C)", correctAnswer: "c", explanation: "Heading (T) = 022 + 7 = 029; +16 W var → 045° (M); dev = −2 − 4·sin045 + 3·cos045 = −2.7; compass = 045 − (−2.7) = 047.7° (C).", difficulty: "hard" },
  { id: "INS-1407", sectionId: "A.7.7", question: "Compass deviation is:", optionA: "the difference in the location of the Earth's Magnetic and Geographic Poles", optionB: "caused by the angle of magnetic dip", optionC: "caused by aircraft magnetism distorting the Earth's magnetic field", optionD: "the angle between true north and compass north", correctAnswer: "c", explanation: "Deviation is the compass error produced by the aircraft's own magnetism distorting the earth's field at the compass.", difficulty: "medium" },
  { id: "INS-1408", sectionId: "A.7.7", question: "With reference to compass deviation: (1) Coefficient A is constant on all headings. (2) Coefficient B varies as cosine heading. (3) Coefficient C varies as cosine heading. (4) Coefficient A varies with aircraft heading. (5) Coefficient C is calculated using the formula: (dev N − dev S) ÷ 2.", optionA: "2, 3 and 5 are correct", optionB: "1, 3, and 5 are correct", optionC: "1, 4 and 5 are correct", optionD: "2, 4 and 5 are correct", correctAnswer: "b", explanation: "Coefficient A is constant on all headings (1); C varies as cosine (3) and equals (dev N − dev S)/2 (5). Coefficient B varies as SINE heading.", difficulty: "hard" },
  { id: "INS-1409", sectionId: "A.7.7", question: "With reference to Coefficients A, B and C:", optionA: "correction for Coefficient A is made by the micro-adjuster", optionB: "Coefficient B is caused by Parameters Q and cZ which causes maximum deviations on east and west headings", optionC: "Coefficient C is caused by Parameters Q and fZ giving maximum deviations on north and south headings", optionD: "Coefficient C is caused by Parameters P and cZ giving maximum deviations on east and west headings", correctAnswer: "a", explanation: "Coefficient A (a constant deviation on all headings) is corrected mechanically with the micro-adjuster.", difficulty: "hard" },
  { id: "INS-1410", sectionId: "A.7.7", question: "Coefficient A +3 is corrected on heading 300° (C). The compass reading after correction for Coefficient A is:", optionA: "330° (C)", optionB: "303° (C)", optionC: "297° (C)", optionD: "300° (C)", correctAnswer: "b", explanation: "Removing a +3° coefficient A shifts the reading by +3°: 300 + 3 = 303° (C).", difficulty: "medium" },

  // ── Ch15 Magnetic Compass → A.7.7 ──
  { id: "INS-1501", sectionId: "A.7.7", question: "With reference to the magnetic compass: (1) The purpose of the bellows is to remove air bubbles from the liquid as it swirls. (2) Aperiodicity in the compass is partially achieved by the compass liquid. (3) Compass sensitivity is achieved by using just one large magnet. (4) Liquid swirl is an ideal quality because it allows the compass card to stop turning immediately a turn has been completed. (5) The sensitivity of the compass can be increased through the use of two or four short magnets. (6) Compensation for expansion and contraction of the fluid due to temperature changes is achieved by the bellows.", optionA: "1, 2 and 5 are correct", optionB: "2, 5 and 6 are correct", optionC: "1, 4 and 5 are correct", optionD: "2, 3 and 6 are correct", correctAnswer: "b", explanation: "Aperiodicity is partly from the liquid (2); sensitivity from 2–4 short magnets (5); the bellows compensate for fluid expansion/contraction (6). The bellows are not for air bubbles, and liquid swirl is an undesirable error.", difficulty: "hard" },
  { id: "INS-1502", sectionId: "A.7.7", question: "An aircraft is accelerating on an easterly heading in the southern hemisphere. Seen from above, the magnetic assembly will:", optionA: "rotate to the left indicating a turn towards the north", optionB: "rotate to the right indicating a turn towards the south", optionC: "rotate to the left indicating a turn towards the south", optionD: "rotate to the right indicating a turn towards the north", correctAnswer: "c", explanation: "In the Southern Hemisphere acceleration on east/west gives an apparent turn to the South — the card rotates left.", difficulty: "hard" },
  { id: "INS-1503", sectionId: "A.7.7", question: "Horizontality of a compass is achieved by:", optionA: "using two or four short magnets, rather than one long one", optionB: "filling the compass bowl with a liquid and attaching damping wires to the assembly", optionC: "locating the CG of the magnetic assembly at the pivot point", optionD: "mounting the magnetic assembly with its CG below the pivot point", correctAnswer: "d", explanation: "Suspending the magnet pendulously (CG below the pivot) keeps the card near horizontal despite magnetic dip.", difficulty: "medium" },
  { id: "INS-1504", sectionId: "A.7.7", question: "An aircraft is decelerating on an easterly heading in the southern hemisphere. Seen from above, the magnetic assembly will:", optionA: "rotate to the left indicating a turn towards the north", optionB: "rotate to the right indicating a turn towards the north", optionC: "rotate to the left indicating a turn towards the south", optionD: "rotate to the right indicating a turn towards the south", correctAnswer: "b", explanation: "In the Southern Hemisphere deceleration on east/west gives an apparent turn to the North — the card rotates right.", difficulty: "hard" },
  { id: "INS-1505", sectionId: "A.7.7", question: "An aircraft is turning right from 150° (C) onto 220° (C) in the Southern Hemisphere. An appropriate compass heading for the aircraft to roll out on would be:", optionA: "210° (C)", optionB: "220° (C)", optionC: "230° (C)", optionD: "240° (C)", correctAnswer: "a", explanation: "Turning through south in the Southern Hemisphere you UNDERSHOOT (ONUS), rolling out early — about 210° for a target of 220°.", difficulty: "hard" },
  { id: "INS-1506", sectionId: "A.7.7", question: "A magnetic compass will show an apparent turn to the North in the Southern Hemisphere when:", optionA: "the aircraft accelerates on 000° (C)", optionB: "the aircraft accelerates on 090° (C)", optionC: "the aircraft decelerates on 270° (C)", optionD: "the aircraft accelerates on 270° (C)", correctAnswer: "c", explanation: "In the Southern Hemisphere deceleration on an east/west heading gives an apparent turn North — here decelerating on 270°.", difficulty: "hard" },
  { id: "INS-1507", sectionId: "A.7.7", question: "Aperiodicity in a magnetic compass:", optionA: "is achieved by using a single magnet", optionB: "refers to the ability of the compass to sense changes in the earth's magnetic field", optionC: "is achieved by locating the CG of the magnetic assembly below the pivot", optionD: "means that following a change in heading, the compass does not oscillate", correctAnswer: "d", explanation: "An aperiodic compass settles on a new heading in one movement without oscillating.", difficulty: "medium" },
  { id: "INS-1508", sectionId: "A.7.7", question: "Residual dip, or tilt, in a magnetic compass:", optionA: "occurs only near the magnetic poles", optionB: "refers to the final inclination of the compass magnet as a result of the effect of the CG of the magnetic assembly on force Z", optionC: "is one of the effects of liquid swirl", optionD: "is caused by an imbalance between the CG of the magnetic assembly and the earth's horizontal field", correctAnswer: "b", explanation: "Residual dip is the small remaining tilt (≈2° at mid-latitudes) left after the pendulous CG largely offsets the vertical component Z.", difficulty: "medium" },
  { id: "INS-1509", sectionId: "A.7.7", question: "In a magnetic compass, 2 or 4 magnets are used:", optionA: "the effect of which is to increase the sensitivity", optionB: "in order to counteract the effect of dip near the magnetic poles", optionC: "to improve the aperiodicity of the compass", optionD: "to ensure a quicker response to heading changes and turning error", correctAnswer: "a", explanation: "Several short magnets increase magnetic moment (sensitivity) while keeping the moment of inertia low.", difficulty: "medium" },
  { id: "INS-1510", sectionId: "A.7.7", question: "With reference to turning errors during a turn from north east to north west:", optionA: "in the southern hemisphere, the compass card will rotate to the left", optionB: "in the northern hemisphere, the pilot should overshoot the required heading", optionC: "in the southern hemisphere, the pilot should undershoot the required heading", optionD: "in the northern hemisphere, the compass card will rotate to the left", correctAnswer: "d", explanation: "Turning N/E to N/W (through north) the aircraft turns left; in the Northern Hemisphere the card rotates left with the aircraft.", difficulty: "hard" },

  // ── Ch16 Remote Indicating Compass → A.7.2 ──
  { id: "INS-1601", sectionId: "A.7.2", question: "With reference to the remote indicating compass system. The precession rate of the gyro is kept low:", optionA: "in order to maintain the gyro axis in the horizontal plane", optionB: "in order to suppress turning and acceleration errors", optionC: "in order to allow the master unit to follow the gyro unit", optionD: "through the use of a vertical axis gyro", correctAnswer: "b", explanation: "A low precession rate stops the gyro reacting to short-term turning/acceleration forces, so those errors are suppressed.", difficulty: "medium" },
  { id: "INS-1602", sectionId: "A.7.2", question: "The remote indicating compass system remains synchronised in a turn because:", optionA: "the follow up motor keeps the compass synchronised", optionB: "the precession circuit is activated causing the gyro to follow the turn", optionC: "the signals from the detector unit to the signal selsyn change at the same rate as the rotor of the signal selsyn turns", optionD: "the detector unit aligns itself with the magnetic meridian", correctAnswer: "c", explanation: "The detector (flux valve) signal and the signal-selsyn rotor change together, so the system stays synchronised through the turn.", difficulty: "hard" },
  { id: "INS-1603", sectionId: "A.7.2", question: "The remote indicating compass system does not indicate turning and acceleration errors because of:", optionA: "the annunciator circuits", optionB: "the slow precession rate of the gyro", optionC: "the Hookes joint suspension of the detector unit", optionD: "the fact that the detector unit has no freedom of movement in pitch and roll", correctAnswer: "b", explanation: "The gyro's slow precession rate averages out the short-term turning/acceleration forces, removing those compass errors.", difficulty: "medium" },
  { id: "INS-1604", sectionId: "A.7.2", question: "The remote indicating compass system indicates aircraft heading because:", optionA: "the detector unit senses the angle between the aircraft fore and aft axis and the magnetic meridian", optionB: "the detector unit aligns itself with the magnetic meridian", optionC: "the signal selsyn measures aircraft heading", optionD: "the follow-up motor drives the compass card to magnetic north", correctAnswer: "a", explanation: "The flux detector senses the angle between the aircraft's fore-aft axis and the magnetic meridian, which is the magnetic heading.", difficulty: "medium" },
  { id: "INS-1605", sectionId: "A.7.2", question: "With reference to the remote indicating compass system: (1) Turning and accelerating errors cannot be suppressed. (2) The detector unit is fixed in the horizontal plane (azimuth). (3) The detector unit is free to rotate in the horizontal plane (azimuth). (4) The detector unit has freedom of movement of about 25° in pitch and roll. (5) Corrections for coefficients B and C are made by a remotely controlled electro-magnetic deviation corrector mounted on the top of the detector unit. (6) No correction is required or can be made for coefficient A.", optionA: "1, 3 and 5 are all correct", optionB: "only 2 and 4 are correct", optionC: "2, 5 and 6 are all correct", optionD: "2, 4 and 5 are all correct", correctAnswer: "d", explanation: "The detector is fixed in azimuth (2) with ~25° pitch/roll freedom (4), and coefficients B and C are removed by a remote electro-magnetic corrector (5).", difficulty: "hard" },

  // ── Ch17 Powerplant & System Monitoring Instruments → A.7.9 ──
  { id: "INS-1701", sectionId: "A.7.9", question: "As airspeed increases during the take-off run the effect on the EPR indication is to:", optionA: "cause it to increase requiring the pilot to reduce the thrust setting", optionB: "cause it to decrease requiring the pilot to increase the thrust setting", optionC: "cause it to decrease, but this is only temporary and the thrust setting should not be changed", optionD: "cause an initial increase followed by a return to normal as the aeroplane becomes airborne", correctAnswer: "c", explanation: "Rising airspeed raises the compressor inlet pressure, momentarily lowering the EPR ratio; it is transient, so the thrust setting is not adjusted.", difficulty: "medium" },
  { id: "INS-1702", sectionId: "A.7.9", question: "Engine Pressure Ratio (EPR) is a measure of:", optionA: "the RPM of the high pressure compressor shaft", optionB: "the RPM of the fan in a turbofan engine", optionC: "the difference between turbine pressure and exhaust pressure", optionD: "the thrust produced by a gas turbine engine", correctAnswer: "d", explanation: "EPR (turbine exhaust pressure ÷ compressor inlet pressure) is proportional to, and indicates, the thrust of a gas turbine.", difficulty: "medium" },
  { id: "INS-1703", sectionId: "A.7.9", question: "In a manifold pressure gauge:", optionA: "the evacuated capsule contains an internal spring to enable it to respond to ambient pressure", optionB: "as manifold pressure increases the pressure bellows contract causing a higher reading on the gauge", optionC: "the capsule which is directly connected to the intake manifold contains an internal spring to limit the expansion as power is increased", optionD: "as manifold pressure decreases the pressure bellows expand causing a lower reading on the gauge", correctAnswer: "a", explanation: "The manifold-pressure gauge uses an evacuated (aneroid) bellows with an internal spring so it reads absolute pressure by responding to ambient pressure, plus a bellows linked to manifold pressure.", difficulty: "hard" },
  { id: "INS-1704", sectionId: "A.7.9", question: "A vibration meter installed on gas turbine engines:", optionA: "measures the frequency of vibrations", optionB: "measures the maximum amplitude of vibrations against a pre-set value, to indicate abnormal operation", optionC: "measures the minimum amplitude of vibrations against a pre-set value, to indicate abnormal operation", optionD: "measures the rotational force of the turbine", correctAnswer: "b", explanation: "The vibration monitor compares the maximum vibration amplitude with a preset level and warns (amber) if abnormal vibration is exceeded.", difficulty: "medium" },
  { id: "INS-1705", sectionId: "A.7.9", question: "The capacitance type fuel gauge system operates on the principle of:", optionA: "measuring the changes in dielectric resistance", optionB: "measuring the dielectric resistance between fuel and water", optionC: "measuring the dielectric resistance between fuel and air", optionD: "measuring the changes in dielectric capacitance", correctAnswer: "d", explanation: "The tank probe is a capacitor whose dielectric (fuel vs air) changes with fuel level, so capacitance indicates quantity (by mass).", difficulty: "medium" },
  { id: "INS-1706", sectionId: "A.7.9", question: "On fuel injected piston engines, the fuel flow is measured:", optionA: "as it leaves the fuel supply tank", optionB: "as it enters the combustion chamber", optionC: "at the fuel intake of each engine", optionD: "before it enters the fuel pump", correctAnswer: "c", explanation: "On a fuel-injected piston engine, fuel flow is sensed at the fuel intake/injection point of the engine (fuel-injection nozzle pressure).", difficulty: "medium" },
];

// The AVEX chapter-end bank plus the standard 022 (ECQB) instrumentation bank.
export const ALL_INSTRUMENTS_QUESTIONS: AirLawQuestion[] = [
  ...INSTRUMENTS_QUESTIONS,
  ...INSTRUMENTS_ECQB_QUESTIONS,
  ...INSTRUMENTS_GAP_QUESTIONS,
];

export function getInstrumentsQuestionsBySection(sectionId: string): AirLawQuestion[] {
  return ALL_INSTRUMENTS_QUESTIONS.filter((q) => q.sectionId === sectionId);
}
